INSERT INTO _teaser_card_plan (site_id, column_name, old_value, new_value, change_key, reason, premise, evidence) VALUES
    ('00980091-cbe8-4838-acff-78d936585d4c'::uuid, 'card_description', 'The town was one of two fortified towns founded to mark Emperor Trajan’s victory in 105-106 AD over the Dacians.', 'By the Mesta river lie the ruins of Nicopolis ad Nestum, a Roman town founded to mark Trajan''s victory over the Dacians, where over 95 gold coins and a statuette of Hermes were found.', 'teaser-card-s012:00980091-cbe8-4838-acff-78d936585d4c:card_description', 'teaser-card-s012 (teaser-card): teaser card, 183 characters, checked PASS, web-verified VERIFIED', '4f18526d58905642f1646c0388cc9fa9051771a2bbc94962b6888d588bb1ad13|ec9bdf2b233d991a24bca7e2b3563c8d4bcc3241d33fba247cd7180ecfd216d8|ec9bdf2b233d991a24bca7e2b3563c8d4bcc3241d33fba247cd7180ecfd216d8', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "By the Mesta river lie the ruins of Nicopolis ad Nestum, a Roman town founded to mark Trajan''s victory over the Dacians, where over 95 gold coins and a statuette of Hermes were found."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the site lies by the Mesta river [S1]; it is the ruins of a Roman town [S1]; the town was founded to mark a victory [S2]; the victory was Trajan''s [S2]; the victory was over the Dacians [S2]; over 95 gold coins were found there [S7]; a statuette of Hermes was found there [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-001 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Central claim: Nicopolis ad Nestum is a Roman town (a settlement whose ruins survive) [SUPPORTED: https://en.wikipedia.org/wiki/Nicopolis_ad_Nestum]; The town lies in ruins today [SUPPORTED: https://en.wikipedia.org/wiki/Nicopolis_ad_Nestum]; The ruins lie by the Mesta river (in Bulgaria) [SUPPORTED: https://en.wikipedia.org/wiki/Nicopolis_ad_Nestum]; The town was founded to mark a victory [SUPPORTED: https://en.wikipedia.org/wiki/Nicopolis_ad_Nestum]; The victory it marks was Trajan''s [SUPPORTED: https://en.wikipedia.org/wiki/Nicopolis_ad_Nestum]; The victory was over the Dacians [SUPPORTED: https://en.wikipedia.org/wiki/Nicopolis_ad_Nestum]; Over 95 gold coins were found at the site [SUPPORTED: https://en.wikipedia.org/wiki/Nicopolis_ad_Nestum]; A statuette of Hermes was found at the site [SUPPORTED: https://en.wikipedia.org/wiki/Nicopolis_ad_Nestum]"}]'::jsonb),
    ('021e7e01-8d62-4480-ae4a-454bc7d78b7f'::uuid, 'card_description', 'Roman lakeside settlement on the Obersee shore, positioned at the junction of roads to Zurich, Winterthur, and Chur. A 1st-century waystation on the Alpine road network.', 'Underneath Busskirch church lie Roman ruins excavated in 1975, a lakeside Roman site that began in the 1st century A.D. Come and stand above what the Romans left.', 'teaser-card-s012:021e7e01-8d62-4480-ae4a-454bc7d78b7f:card_description', 'teaser-card-s012 (teaser-card): teaser card, 162 characters, checked PASS, web-verified VERIFIED', '1e1b5f48204efe1df793a23a922aeb82b9b1862b38c0f874ff036b8650aef028|9da01e4b9f55c71fe6b052da4cb0869188596d4330a01debc7e1045427a3c84a|9da01e4b9f55c71fe6b052da4cb0869188596d4330a01debc7e1045427a3c84a', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-rewrite-v-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Underneath Busskirch church lie Roman ruins excavated in 1975, a lakeside Roman site that began in the 1st century A.D. Come and stand above what the Romans left."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-v-001 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Roman ruins lie underneath Busskirch church [S2]; the Roman ruins were excavated in 1975 [S2]; the site is a lakeside Roman site [S1]; the Roman site began in the 1st century A.D. [S1]; visitors can stand above the Roman remains left underneath the church [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify2-001 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Busskirch is a Roman lakeside site (settlement), at the church of Busskirch on the Obersee shore, Switzerland [SUPPORTED: https://en.wikipedia.org/wiki/Busskirch]; The Roman site began in the 1st century A.D. [SUPPORTED: https://en.wikipedia.org/wiki/Busskirch]; Roman ruins lie underneath Busskirch church [SUPPORTED: https://en.wikipedia.org/wiki/Busskirch]; The Roman ruins under the church were excavated in 1975 [SUPPORTED: https://en.wikipedia.org/wiki/Busskirch]; The church (St. Martin) stands on the remains of a Roman building, so one can stand above what the Romans left [SUPPORTED: https://en.wikipedia.org/wiki/Busskirch]"}]'::jsonb),
    ('0259ff6b-ef34-4a7e-93ef-78e2729e45a6'::uuid, 'card_description', 'Rock art spanning the Mesolithic to the Middle Bronze Age, including geometric, animal, and human images. Part of the Council of Europe''s Prehistoric Rock Art Trails.', 'In a narrow gorge, the Trialeti Petroglyphs spread about 100 images across 50 m of flat basalt: deer, horses, fantastic and hybrid creatures, and diminutive hunters with bows and arrows.', 'teaser-card-s012:0259ff6b-ef34-4a7e-93ef-78e2729e45a6:card_description', 'teaser-card-s012 (teaser-card): teaser card, 186 characters, checked PASS, web-verified VERIFIED', '6cad36b0953bc41b86ed2a0ff19dba15f074c68d0ef23b3ec96f3b6f823ed90e|26c5237c4a05e9ddc7ca1282f175dc6f05ea5844f318b7583f4501560995f945|26c5237c4a05e9ddc7ca1282f175dc6f05ea5844f318b7583f4501560995f945', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "In a narrow gorge, the Trialeti Petroglyphs spread about 100 images across 50 m of flat basalt: deer, horses, fantastic and hybrid creatures, and diminutive hunters with bows and arrows."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the petroglyphs are in a narrow gorge [S3]; there are about 100 images [S5]; the images spread across 50 m [S5]; the surface is flat basalt [S5]; the images include deer and horses [S6]; the images include fantastic and hybrid creatures [S6]; the images include hunters with bows and arrows [S7]; the hunters are diminutive [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-001 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Central claim: the Trialeti Petroglyphs are a prehistoric rock art site (petroglyphs) in the Trialeti area of Georgia [SUPPORTED: https://en.wikipedia.org/wiki/Trialeti_petroglyphs]; The petroglyphs lie in a narrow gorge [SUPPORTED: https://en.wikipedia.org/wiki/Trialeti_petroglyphs]; There are about 100 images [SUPPORTED: https://en.wikipedia.org/wiki/Trialeti_petroglyphs]; The images are spread across 50 m [SUPPORTED: https://en.wikipedia.org/wiki/Trialeti_petroglyphs]; The surface is flat basalt [SUPPORTED: https://en.wikipedia.org/wiki/Trialeti_petroglyphs]; The images include deer [SUPPORTED: https://en.wikipedia.org/wiki/Trialeti_petroglyphs]; The images include horses [SUPPORTED: https://en.wikipedia.org/wiki/Trialeti_petroglyphs]; The images include fantastic and hybrid creatures [SUPPORTED: https://en.wikipedia.org/wiki/Trialeti_petroglyphs]; The images include diminutive hunters [SUPPORTED: https://en.wikipedia.org/wiki/Trialeti_petroglyphs]; The hunters carry bows and arrows [SUPPORTED: https://en.wikipedia.org/wiki/Trialeti_petroglyphs]"}]'::jsonb),
    ('02a9d200-6a8f-40aa-92a1-79182e38c822'::uuid, 'card_description', '4th-millennium BC necropolis in Huelva found in 2022. A 2023 stela shows a headdress, necklace, two swords, and male genitalia, described as gender ambiguous by excavators from Seville and Durham.', 'At Las Capellanías in Huelva, a stela found in 2023 is carved with a headdress and necklace, usually associated with female burials, yet also two swords. Described as gender-bending.', 'teaser-card-s012:02a9d200-6a8f-40aa-92a1-79182e38c822:card_description', 'teaser-card-s012 (teaser-card): teaser card, 182 characters, checked PASS, web-verified VERIFIED', '352e944313ccf6c0108523c4f738dad189d386962527605622f9518235d60d85|380fe7e3ae88caef6e17fe332a0b14af22313571f7baa5f7fa882cf41f2f0c7e|380fe7e3ae88caef6e17fe332a0b14af22313571f7baa5f7fa882cf41f2f0c7e', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-rewrite1-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "At Las Capellanías in Huelva, a stela found in 2023 is carved with a headdress and necklace, usually associated with female burials, yet also two swords. Described as gender-bending."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check1-001 (check1), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the site is Las Capellanías, in Huelva [S1]; a stela was found there in 2023 [S4]; the stela is carved with a headdress and a necklace [S4]; a headdress and necklace are usually associated with female burials [S4]; the stela is also carved with two swords [S4]; the stela has been described as gender-bending [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-001 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Central claim: Las Capellanías is a prehistoric funerary complex in Huelva, Spain [SUPPORTED: https://en.wikipedia.org/wiki/Las_Capellan%C3%ADas]; A stela was found at the site in 2023 [SUPPORTED: https://en.wikipedia.org/wiki/Las_Capellan%C3%ADas]; The stela is carved with a headdress [SUPPORTED: https://en.wikipedia.org/wiki/Las_Capellan%C3%ADas]; The stela is carved with a necklace [SUPPORTED: https://en.wikipedia.org/wiki/Las_Capellan%C3%ADas]; Headdress and necklace are usually associated with female burials [SUPPORTED: https://en.wikipedia.org/wiki/Las_Capellan%C3%ADas]; The stela is also carved with two swords [SUPPORTED: https://en.wikipedia.org/wiki/Las_Capellan%C3%ADas]; The stela has been described as gender-bending [SUPPORTED: https://en.wikipedia.org/wiki/Las_Capellan%C3%ADas]; The site is at Las Capellanías in (the province of) Huelva [SUPPORTED: https://en.wikipedia.org/wiki/Las_Capellan%C3%ADas]"}]'::jsonb),
    ('02dbd963-d64f-4c40-a267-2ad5b2ea821a'::uuid, 'card_description', 'Occupied from 600 BC to 1500 AD, this Maya site is famous for the Satunsat — a building designed as a labyrinth replicating a cave, with ventilation shafts aligned to celestial events.', 'In the Puuc region of Yucatán, the Maya center of Oxkintok keeps The Labyrinth, explored in 1842, and, on the lintel of Structure 6, a very early Long Count date: 475 CE.', 'teaser-card-s012:02dbd963-d64f-4c40-a267-2ad5b2ea821a:card_description', 'teaser-card-s012 (teaser-card): teaser card, 170 characters, checked PASS, web-verified VERIFIED', '36007230c7b55931ef3840de6255eb5f739330f9bb6e9b2c9464e2cc6c7c2fa6|14669da123b35e4fd4bea3f8c131e698caf9fac6552e20f7579348103cc84cea|14669da123b35e4fd4bea3f8c131e698caf9fac6552e20f7579348103cc84cea', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "In the Puuc region of Yucatán, the Maya center of Oxkintok keeps The Labyrinth, explored in 1842, and, on the lintel of Structure 6, a very early Long Count date: 475 CE."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Oxkintok is in the Puuc region [S1]; the Puuc region is in Yucatan [S1]; Oxkintok is Maya [S1]; Oxkintok was a center [S6]; The Labyrinth is at Oxkintok [S3]; The Labyrinth was explored in 1842 [S3]; the lintel of Structure 6 bears a Long Count date [S7]; the date is very early [S7]; the date is 475 CE [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-001 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Central claim: Oxkintok is a Maya center (archaeological site) [SUPPORTED: https://en.wikipedia.org/wiki/Oxkintok]; Oxkintok lies in the Puuc region [SUPPORTED: https://en.wikipedia.org/wiki/Oxkintok]; Oxkintok lies in Yucatán (Mexico) [SUPPORTED: https://en.wikipedia.org/wiki/Oxkintok]; Oxkintok has a structure known as The Labyrinth [SUPPORTED: https://en.wikipedia.org/wiki/Oxkintok]; The Labyrinth was explored in 1842 [SUPPORTED: https://en.wikipedia.org/wiki/Oxkintok]; The lintel of Structure 6 carries a Long Count date [SUPPORTED: https://en.wikipedia.org/wiki/Oxkintok]; The Long Count date is 475 CE [SUPPORTED: https://en.wikipedia.org/wiki/Oxkintok]; The date is very early for the Long Count [SUPPORTED: https://en.wikipedia.org/wiki/Oxkintok]; The date is on the lintel of Structure 6 [SUPPORTED: https://mexicounexplained.com/oxkintok-little-known-lost-city-of-the-maya/]"}]'::jsonb),
    ('04c8399c-298d-41ab-bb53-f56beb9e45da'::uuid, 'card_description', 'Twyn y Gaer crowns the summit of this Black Mountains ridge at 427 metres. The hillfort commands views over both the Grwyne Fawr valley to the east and the Vale of Ewyas to the west.', 'At the southern end of a long ridge in the Black Mountains, the summit of the hill called Gaer, 427m above sea level, sits within an Iron Age hillfort known as Twyn y Gaer.', 'teaser-card-s012:04c8399c-298d-41ab-bb53-f56beb9e45da:card_description', 'teaser-card-s012 (teaser-card): teaser card, 172 characters, checked PASS, web-verified VERIFIED', 'f2577c15714db89967ad586544c912549648953d97e7f48f67eef5c370a16623|7627b0a18af8796c431671ce70c0a2617eb4266c83ee55c9b90b28a28254b68b|7627b0a18af8796c431671ce70c0a2617eb4266c83ee55c9b90b28a28254b68b', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "At the southern end of a long ridge in the Black Mountains, the summit of the hill called Gaer, 427m above sea level, sits within an Iron Age hillfort known as Twyn y Gaer."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Gaer is at the southern end of a long ridge [S2]; Gaer is in the Black Mountains [S1]; Gaer is a hill [S1]; its summit is 427 m above sea level [S3]; the summit sits within an Iron Age hillfort [S3]; the hillfort is known as Twyn y Gaer [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-verify-002 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Gaer is a hill whose summit is occupied by an Iron Age hillfort (the site is a hillfort on a hill) [SUPPORTED: https://en.wikipedia.org/wiki/Gaer_(Black_Mountains)]; Gaer is in the Black Mountains [SUPPORTED: https://en.wikipedia.org/wiki/Gaer_(Black_Mountains)]; Gaer is in Wales [SUPPORTED: https://en.wikipedia.org/wiki/Gaer_(Black_Mountains)]; The hill lies at the southern end of a long ridge [SUPPORTED: https://en.wikipedia.org/wiki/Gaer_(Black_Mountains)]; The summit of Gaer is 427 m above sea level [SUPPORTED: https://en.wikipedia.org/wiki/Gaer_(Black_Mountains)]; The summit sits within a hillfort [SUPPORTED: https://en.wikipedia.org/wiki/Gaer_(Black_Mountains)]; The hillfort dates to the Iron Age [SUPPORTED: https://en.wikipedia.org/wiki/Gaer_(Black_Mountains)]; The hillfort is known as Twyn y Gaer [SUPPORTED: https://en.wikipedia.org/wiki/Gaer_(Black_Mountains)]"}]'::jsonb),
    ('05ee235c-2ded-4af5-9e94-980c7750bc52'::uuid, 'card_description', 'The Trundle is a hillfort on St Roche''s Hill about 4 miles north of Chichester, West Sussex. The Trundle was listed as a scheduled monument in 1933.', 'The Trundle, an Iron Age hillfort, hid a Neolithic site unknown until an aerial photograph in 1925: a causewayed enclosure of at least four circular or partly circular ditches.', 'teaser-card-s012:05ee235c-2ded-4af5-9e94-980c7750bc52:card_description', 'teaser-card-s012 (teaser-card): teaser card, 176 characters, checked PASS, web-verified VERIFIED', 'e8ab93df1a8091b2c539ce6d73908b16876317df261f5e03eeb99ca7004621b5|fb5c138c22f0de3488780cf590f8b2b7fe90aed5d4b8c13710fd61625919fb4f|fb5c138c22f0de3488780cf590f8b2b7fe90aed5d4b8c13710fd61625919fb4f', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "The Trundle, an Iron Age hillfort, hid a Neolithic site unknown until an aerial photograph in 1925: a causewayed enclosure of at least four circular or partly circular ditches."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "The Trundle is an Iron Age hillfort [S1, S2]; the hillfort lies on (hid) a Neolithic site [S2, S3]; the Neolithic site was unknown until 1925 [S3]; an aerial photograph in 1925 revealed it [S3]; the Neolithic site is a causewayed enclosure [S2]; the enclosure consists of at least four circular or partly circular ditches [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-verify-002 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "The Trundle is a hillfort (in England, West Sussex) [SUPPORTED: https://en.wikipedia.org/wiki/The_Trundle]; The Trundle hillfort is Iron Age [SUPPORTED: https://en.wikipedia.org/wiki/The_Trundle]; The hillfort was built on top of (hid) a Neolithic site, a causewayed enclosure [SUPPORTED: https://en.wikipedia.org/wiki/The_Trundle]; The Neolithic site was unknown until 1925 [SUPPORTED: https://en.wikipedia.org/wiki/The_Trundle]; It was discovered through an aerial photograph [SUPPORTED: https://en.wikipedia.org/wiki/The_Trundle]; The Neolithic site is a causewayed enclosure [SUPPORTED: https://en.wikipedia.org/wiki/The_Trundle]; The causewayed enclosure consists of at least four circular or partly circular ditches [SUPPORTED: https://en.wikipedia.org/wiki/The_Trundle]"}]'::jsonb),
    ('0608f0dc-4dd4-420e-ad27-ea59fe561212'::uuid, 'card_description', 'A fortified settlement dating to 7000 BC—one of the earliest walled sites known. It preserves the development of pre-Hassuna culture in Mesopotamia.', 'By the Abra River rises Tell Maghzaliyah, a fortified aceramic Mesolithic and Neolithic site whose deposits reach approximately 8 meters deep, with connections to the Jarmo culture.', 'teaser-card-s012:0608f0dc-4dd4-420e-ad27-ea59fe561212:card_description', 'teaser-card-s012 (teaser-card): teaser card, 181 characters, checked PASS, web-verified VERIFIED', 'f758bdb58899d3d16b6e7a2ab0fb4c17284bc24066ba8ece98009afac7ccb28e|2102027847efa27e6714113b64a531c3ee9b035451849c214b03046958bc4ae7|2102027847efa27e6714113b64a531c3ee9b035451849c214b03046958bc4ae7', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "By the Abra River rises Tell Maghzaliyah, a fortified aceramic Mesolithic and Neolithic site whose deposits reach approximately 8 meters deep, with connections to the Jarmo culture."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Tell Maghzaliyah is by the Abra River [S2]; it is fortified [S1]; it is aceramic [S1]; it is a Mesolithic and Neolithic site [S1]; its deposits are approximately 8 meters deep [S5]; it has connections to the Jarmo culture [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-verify-002 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Tell Maghzaliyah is a prehistoric archaeological site (a tell/settlement) in Iraq [SUPPORTED: https://en.wikipedia.org/wiki/Tell_Maghzaliyah]; The site is fortified [SUPPORTED: https://en.wikipedia.org/wiki/Tell_Maghzaliyah]; The site is aceramic [SUPPORTED: https://en.wikipedia.org/wiki/Tell_Maghzaliyah]; The site is Mesolithic and Neolithic [SUPPORTED: https://en.wikipedia.org/wiki/Tell_Maghzaliyah]; The site lies by the Abra River [SUPPORTED: https://en.wikipedia.org/wiki/Tell_Maghzaliyah]; The deposits reach approximately 8 meters deep [SUPPORTED: https://en.wikipedia.org/wiki/Tell_Maghzaliyah]; The site has connections to the Jarmo culture [SUPPORTED: https://en.wikipedia.org/wiki/Tell_Maghzaliyah]"}]'::jsonb),
    ('061c9bb7-bfdf-402b-8a85-34376f18172e'::uuid, 'card_description', 'Chief town of the Vestini on the Via Claudia Nova. It was the birthplace of Gnaeus Domitius Corbulo, one of Rome''s greatest generals under Emperor Nero.', 'On a plateau over 100 m above its surroundings, the Roman town of Peltuinum has yielded a temple and a theatre. The earthquake of 443 damaged it, and its people began to leave.', 'teaser-card-s012:061c9bb7-bfdf-402b-8a85-34376f18172e:card_description', 'teaser-card-s012 (teaser-card): teaser card, 176 characters, checked PASS, web-verified VERIFIED', '9fa58dcddd1ec33011a08e2090e954d6773fbc503339ff5b0ffda321f4f7b9b5|520a8b55ada88b34d3e41bafffdea82e232f46aaffbfdc14a34f0643ddd68ed3|520a8b55ada88b34d3e41bafffdea82e232f46aaffbfdc14a34f0643ddd68ed3', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "On a plateau over 100 m above its surroundings, the Roman town of Peltuinum has yielded a temple and a theatre. The earthquake of 443 damaged it, and its people began to leave."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Peltuinum is on a plateau [S7]; the plateau is over 100 m above the surroundings [S7]; Peltuinum is a Roman town [S1]; excavations have yielded a temple [S3]; excavations have yielded a theatre [S3]; the earthquake of 443 damaged it [S5]; its people began to leave [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-verify-002 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Peltuinum was a Roman town [SUPPORTED: https://en.wikipedia.org/wiki/Peltuinum]; Peltuinum is in Italy [SUPPORTED: https://en.wikipedia.org/wiki/Peltuinum]; The town stands on a plateau over 100 m above its surroundings [SUPPORTED: https://en.wikipedia.org/wiki/Peltuinum]; Excavations at Peltuinum have brought to light a temple [SUPPORTED: https://en.wikipedia.org/wiki/Peltuinum]; Excavations at Peltuinum have brought to light a theatre [SUPPORTED: https://en.wikipedia.org/wiki/Peltuinum]; The earthquake of 443 damaged Peltuinum [SUPPORTED: https://en.wikipedia.org/wiki/Peltuinum]; After the earthquake the population began to leave the city [SUPPORTED: https://en.wikipedia.org/wiki/Peltuinum]"}]'::jsonb),
    ('06a44374-50d9-4bc1-b747-41fa09e28eee'::uuid, 'card_description', 'About 30 pre-Inca chullpa burial towers perched at 3,000 metres elevation. Chullpas were built so the dead could face the rising sun in an eternal vigil.', NULL, 'teaser-card-s012:06a44374-50d9-4bc1-b747-41fa09e28eee:card_description', 'teaser-card-s012 (card-clear-unproven-after-verify): card cleared (unproven-after-verify)', '||e4830f5c5c4a3c8a747fec5a44aec0542f2d6ae5195d3b952b04c1f42c1dc062', '[{"source": "lane WB run wb-ws-2026-09-27-01: unproven-after-verify", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "The web check contradicts: The site lies at about 3,000 m elevation (Wikipedia and a copy of the Peruvian tourism-resource sheet say 3,000 m, but the municipal page of Paucartambo, two further pages and a terrain model at the site coordinates, about 3,680 m, give about 3,600 m) (https://paucartambo.info/turismo/chullpas-de-ninamarca: \"esta a una altura de 3,600 msnm\"); The web check could not prove: Ninamarca is an archaeological site in Peru (a chullpa site)"}]'::jsonb),
    ('06b4c496-930b-45ac-a8f4-3e4831de1a50'::uuid, 'card_description', 'Iron Age univallate hillfort in the Mendip Hills, Somerset, 1st millennium BC. Its narrow summit bank suggests a dry-stone rampart; the northeast defences have been progressively quarried away.', 'In the Mendip Hills, Westbury Camp is an Iron Age hill fort whose bank, narrow at its top, may once have carried a dry stone wall; small quarries largely destroyed its north east defences.', 'teaser-card-s012:06b4c496-930b-45ac-a8f4-3e4831de1a50:card_description', 'teaser-card-s012 (teaser-card): teaser card, 188 characters, checked PASS, web-verified VERIFIED', 'cd99689209d05b76c3966a25f9b40b4fe58a75717bd5a581b8e57dd6ecd80282|afd3d5cb90e31da945ba4d4f0f96bd02fdc9fde89fcd57fd9005936916c91390|afd3d5cb90e31da945ba4d4f0f96bd02fdc9fde89fcd57fd9005936916c91390', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-rewrite1-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "In the Mendip Hills, Westbury Camp is an Iron Age hill fort whose bank, narrow at its top, may once have carried a dry stone wall; small quarries largely destroyed its north east defences."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check1-001 (check1), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Westbury Camp is in the Mendip Hills [S1]; Westbury Camp is an Iron Age hill fort [S1]; its bank is narrow at the top [S5]; the bank may once have been surmounted by a dry stone wall (hedged) [S5]; small quarries largely destroyed its north east defences [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-003 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Westbury Camp is a hill fort (central claim: the kind of place) [SUPPORTED: https://en.wikipedia.org/wiki/Westbury_Camp]; The hill fort dates to the Iron Age [SUPPORTED: https://en.wikipedia.org/wiki/Westbury_Camp]; The hill fort is in the Mendip Hills [SUPPORTED: https://en.wikipedia.org/wiki/Westbury_Camp]; The top of the hill bank is narrow [SUPPORTED: https://en.wikipedia.org/wiki/Westbury_Camp]; The bank may once have carried (been surmounted by) a dry stone wall [SUPPORTED: https://en.wikipedia.org/wiki/Westbury_Camp]; The camp''s north east defences have largely been destroyed [SUPPORTED: https://en.wikipedia.org/wiki/Westbury_Camp]; The destruction was caused by small quarries [SUPPORTED: https://en.wikipedia.org/wiki/Westbury_Camp]"}]'::jsonb),
    ('06f6cb37-39f4-4785-b6ec-7ec6272ac7d4'::uuid, 'card_description', 'Rotherley Down Settlement is an archaeological site of the late Iron Age and Romano-British period on Cranborne Chase.', 'On the brow of a hill on Cranborne Chase, Rotherley Down Settlement was occupied from the first century BC to the third century AD. What is seen today is Pitt Rivers'' partial reconstruction.', 'teaser-card-s012:06f6cb37-39f4-4785-b6ec-7ec6272ac7d4:card_description', 'teaser-card-s012 (teaser-card): teaser card, 190 characters, checked PASS, web-verified VERIFIED', '3b84130b3a4d4574797e4a3f5d8e90e495404c754d4507f3b1ee24eced6c801b|0f2dfa95c81731101e93785e9ad8629f8fe0fe91ce49c801735c860c147a535b|0f2dfa95c81731101e93785e9ad8629f8fe0fe91ce49c801735c860c147a535b', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "On the brow of a hill on Cranborne Chase, Rotherley Down Settlement was occupied from the first century BC to the third century AD. What is seen today is Pitt Rivers'' partial reconstruction."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the settlement is on the brow of a hill [S4]; it is on Cranborne Chase [S1]; it was occupied from the first century BC to the third century AD [S8]; what is seen today is a partial reconstruction [S6]; the reconstruction is by Pitt Rivers [S5, S6]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-003 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Rotherley Down Settlement is an archaeological site (a settlement) of the late Iron Age and Romano-British period on Cranborne Chase (central claim: kind of place and location) [SUPPORTED: https://en.wikipedia.org/wiki/Rotherley_Down_Settlement]; The site lies on the brow of a hill [SUPPORTED: https://en.wikipedia.org/wiki/Rotherley_Down_Settlement]; The settlement was occupied from the first century BC [SUPPORTED: https://en.wikipedia.org/wiki/Rotherley_Down_Settlement]; The settlement was occupied until the third century AD [SUPPORTED: https://en.wikipedia.org/wiki/Rotherley_Down_Settlement]; What is seen at the site today is a reconstruction [SUPPORTED: https://en.wikipedia.org/wiki/Rotherley_Down_Settlement]; The reconstruction is by Augustus Pitt Rivers, who excavated the site [SUPPORTED: https://en.wikipedia.org/wiki/Rotherley_Down_Settlement]; The reconstruction is only partial [SUPPORTED: https://en.wikipedia.org/wiki/Rotherley_Down_Settlement]"}]'::jsonb),
    ('08d4b7da-794b-4cb7-9ed8-714758ae4487'::uuid, 'card_description', 'A Roman walled town completely abandoned in the early 5th century. The entire settlement lay undiscovered near Marlborough for over 1,500 years.', 'Cunetio was a large walled town in a valley of the River Kennet in Wiltshire. In 1978 the Cunetio Hoard came to light there: 54,951 coins weighing over 180 kilograms.', 'teaser-card-s012:08d4b7da-794b-4cb7-9ed8-714758ae4487:card_description', 'teaser-card-s012 (teaser-card): teaser card, 166 characters, checked PASS, web-verified VERIFIED', '27225ee08e64cb8a346f62e3c5d0cd47b42fe65b7a048d8ec710d708988575c9|bc8eaed7864c76f1123155f586e5fa0346f300a22b389e31b3fe1bdd7c437516|bc8eaed7864c76f1123155f586e5fa0346f300a22b389e31b3fe1bdd7c437516', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-rewrite-v-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Cunetio was a large walled town in a valley of the River Kennet in Wiltshire. In 1978 the Cunetio Hoard came to light there: 54,951 coins weighing over 180 kilograms."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-v-001 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Cunetio was a large town [S1]; Cunetio was a walled town [S1]; it lay in a valley of the River Kennet [S1]; it lay in Wiltshire [S1]; the Cunetio Hoard came to light at Cunetio in 1978 [S4, S5]; the hoard consisted of 54,951 coins [W1]; the coins weighed over 180 kilograms [W1]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify2-001 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Cunetio was a large walled town [SUPPORTED: https://en.wikipedia.org/wiki/Cunetio]; The town lay in a valley of the River Kennet [SUPPORTED: https://en.wikipedia.org/wiki/Cunetio]; The town lay in Wiltshire [SUPPORTED: https://en.wikipedia.org/wiki/Cunetio]; The Cunetio Hoard is a hoard of Roman coins [SUPPORTED: https://en.wikipedia.org/wiki/Cunetio_Hoard]; The Cunetio Hoard came to light at Cunetio in 1978 [SUPPORTED: https://en.wikipedia.org/wiki/Cunetio_Hoard]; The hoard consisted of 54,951 coins [SUPPORTED: https://en.wikipedia.org/wiki/Cunetio_Hoard]; The coins weighed over 180 kilograms [SUPPORTED: https://en.wikipedia.org/wiki/Cunetio_Hoard]"}, {"source": "web fact W1", "url": "https://en.wikipedia.org/wiki/Cunetio_Hoard", "quote": "The 1978 hoard consisted of 54,951 coins weighing over 180 kilograms"}]'::jsonb),
    ('096b583c-5131-43e1-b7e3-4ad0f66f8df8'::uuid, 'card_description', 'A 1st-century BC Roman bridge on the Via Domitia, of which only one of its original eleven arches survives. In the Middle Ages, a chapel to St. Mary was added to the structure.', 'Of the eleven arches that carried the Via Domitia across the Vidourle, one remains: the Pont Ambroix, a Roman bridge of the 1st century BC, left alone mid-river by the floods of 1933.', 'teaser-card-s012:096b583c-5131-43e1-b7e3-4ad0f66f8df8:card_description', 'teaser-card-s012 (teaser-card): teaser card, 183 characters, checked PASS, web-verified VERIFIED', 'e876d7908c4ab02eb38ccc4829d744c17ee60db449beb4f9240c0221edb319cf|af7c120690519cd0b98cd87a5ba59f369fd486b6f78d93953bd53bcf5a317e24|af7c120690519cd0b98cd87a5ba59f369fd486b6f78d93953bd53bcf5a317e24', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Of the eleven arches that carried the Via Domitia across the Vidourle, one remains: the Pont Ambroix, a Roman bridge of the 1st century BC, left alone mid-river by the floods of 1933."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the bridge originally had eleven arches [S3]; the bridge carried the Via Domitia [S1]; the bridge crossed the Vidourle [S2]; one arch remains [S3]; Pont Ambroix is a Roman bridge [S1]; it dates from the 1st century BC [S1]; the remaining arch stands mid-river [S3]; the floods of 1933 left it as a single arch [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-003 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "The Pont Ambroix is a Roman bridge in the south of France (central claim: the kind of place and where it is) [SUPPORTED: https://en.wikipedia.org/wiki/Pont_Ambroix]; The bridge dates from the 1st century BC [SUPPORTED: https://en.wikipedia.org/wiki/Pont_Ambroix]; The bridge carried the Via Domitia [SUPPORTED: https://en.wikipedia.org/wiki/Pont_Ambroix]; The bridge crossed the Vidourle [SUPPORTED: https://en.wikipedia.org/wiki/Pont_Ambroix]; The bridge originally had eleven arches [SUPPORTED: https://en.wikipedia.org/wiki/Pont_Ambroix]; Only one of the eleven arches remains [SUPPORTED: https://en.wikipedia.org/wiki/Pont_Ambroix]; The surviving arch stands alone in the middle of the river [SUPPORTED: https://en.wikipedia.org/wiki/Pont_Ambroix]; The floods of 1933 left the bridge with its single arch (reduced it from two arches to one) [SUPPORTED: https://en.wikipedia.org/wiki/Pont_Ambroix]; In 1933 a flood of the Vidourle destroyed an arch of the Roman bridge (Merimee record) [SUPPORTED: https://www.pop.culture.gouv.fr/notice/merimee/PA00103057]"}]'::jsonb),
    ('09809b93-9c66-424c-ab0e-12cb3052ad31'::uuid, 'card_description', 'The largest of the Bronze Age barrows in Tintagel is at Condolden. The barrow has not been excavated and is topped by an Ordnance Survey triangulation point.', 'On Condolden, the highest point in Tintagel parish, lies the largest Bronze Age barrow in Tintagel, still unexcavated and topped today by an Ordnance Survey trig point.', 'teaser-card-s012:09809b93-9c66-424c-ab0e-12cb3052ad31:card_description', 'teaser-card-s012 (teaser-card): teaser card, 168 characters, checked PASS, web-verified VERIFIED', '1a5926f20d7e586ef62fb4f6cf1ea341a7163d19847910155964021a19aaa97e|69dec859944bc45c6e013bc3550e08336901d759a8c3406f92809ddae511b040|69dec859944bc45c6e013bc3550e08336901d759a8c3406f92809ddae511b040', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "On Condolden, the highest point in Tintagel parish, lies the largest Bronze Age barrow in Tintagel, still unexcavated and topped today by an Ordnance Survey trig point."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Condolden is the highest point in Tintagel parish [S3, S4]; a Bronze Age barrow lies on Condolden [S5]; it is the largest Bronze Age barrow in Tintagel [S5]; the barrow is unexcavated [S6]; the barrow is topped by an Ordnance Survey trig point [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-003 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Condolden is a hill in north Cornwall carrying a Bronze Age barrow (central claim: the kind of place and where it is) [SUPPORTED: https://en.wikipedia.org/wiki/Condolden]; There is a Bronze Age barrow on Condolden [SUPPORTED: https://en.wikipedia.org/wiki/Condolden]; It is the largest Bronze Age barrow in Tintagel [SUPPORTED: https://en.wikipedia.org/wiki/Condolden]; Condolden is the highest point in Tintagel parish [SUPPORTED: https://en.wikipedia.org/wiki/Condolden]; The barrow is topped by an Ordnance Survey trig point [SUPPORTED: https://en.wikipedia.org/wiki/Condolden]; The barrow is still unexcavated (Wikipedia says it ''has not been excavated'', but Historic England reads the mound''s surface hollows as ''probably the result of early partial excavation or robbing'' and Dark Cornwall says it ''has been disturbed in the past, probably by antiquarian digging or stone robbing''; no page settles it) [UNVERIFIABLE, no proving quote: None]"}]'::jsonb),
    ('09fcbc60-19c1-4742-a69d-3cb7afe19443'::uuid, 'card_description', 'Kingston Russell is the largest surviving stone circle in Dorset. The ring consists of eighteen stones, the longest of which are located at the north of the circle.', 'Kingston Russell Stone Circle, the largest surviving in Dorset, has never been excavated. In 1815 one of its stones still stood upright; by 1939 all of them lay on the ground.', 'teaser-card-s012:09fcbc60-19c1-4742-a69d-3cb7afe19443:card_description', 'teaser-card-s012 (teaser-card): teaser card, 175 characters, checked PASS, web-verified VERIFIED', '3a8db9b1947172f367543e6ac0de6e6058802e751dcd91d425248fbb0c61a983|e4cc5376d7761ea94c36080ace884dde177213ba26e9622f77e1521a9e76d6ef|e4cc5376d7761ea94c36080ace884dde177213ba26e9622f77e1521a9e76d6ef', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Kingston Russell Stone Circle, the largest surviving in Dorset, has never been excavated. In 1815 one of its stones still stood upright; by 1939 all of them lay on the ground."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-002 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Kingston Russell Stone Circle is the largest surviving stone circle in Dorset [S5]; the circle has never been excavated [S4]; in 1815 one of its stones still stood upright [S8]; by 1939 all of its stones lay on the ground [S8]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-verify-004 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Kingston Russell Stone Circle is a stone circle in Dorset, England (central claim: kind of place and location) [SUPPORTED: https://en.wikipedia.org/wiki/Kingston_Russell_Stone_Circle]; It is the largest surviving stone circle in Dorset [SUPPORTED: https://en.wikipedia.org/wiki/Kingston_Russell_Stone_Circle]; The site has never been excavated [SUPPORTED: https://en.wikipedia.org/wiki/Kingston_Russell_Stone_Circle]; In 1815 one of its stones still stood upright [SUPPORTED: https://heritage.dorsetcouncil.gov.uk/Monument/MDO1264]; By 1939 all the stones lay on the ground [SUPPORTED: https://en.wikipedia.org/wiki/Kingston_Russell_Stone_Circle]"}]'::jsonb),
    ('0b8a8edd-8a60-4758-985c-bf354de4a985'::uuid, 'card_description', 'King Lud''s Entrenchments is a scheduled monument. The site has not been excavated and its date is unknown.', 'Unexcavated and undated, King Lud''s Entrenchments and The Drift was thought a Saxon boundary ditch, yet aerial photos hint it may belong to a prehistoric boundary running to the Humber.', 'teaser-card-s012:0b8a8edd-8a60-4758-985c-bf354de4a985:card_description', 'teaser-card-s012 (teaser-card): teaser card, 185 characters, checked PASS, web-verified VERIFIED', 'a3215ed1e7e62763e8f8439773eee59e36a5beafde04a39f2411c06858a31e02|54d4833d05106a9037a35e793aa2310fbaa39488d2ede1d4ca804f5d6b297060|54d4833d05106a9037a35e793aa2310fbaa39488d2ede1d4ca804f5d6b297060', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Unexcavated and undated, King Lud''s Entrenchments and The Drift was thought a Saxon boundary ditch, yet aerial photos hint it may belong to a prehistoric boundary running to the Humber."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-002 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the site is unexcavated [S4]; the site is undated (its date is unknown) [S4]; it was thought to be a Saxon boundary ditch [S5]; aerial photographs suggest it may belong to a prehistoric boundary system [S5]; that prehistoric boundary system runs to the Humber [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-004 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "King Lud''s Entrenchments and The Drift is an earthwork, a bank-and-ditch boundary system (central claim: kind of place), on the Leicestershire/Lincolnshire border [SUPPORTED: https://www.megalithic.co.uk/article.php?thold=-1&mode=flat&sid=57170]; The site is unexcavated [SUPPORTED: https://en.wikipedia.org/wiki/King_Lud%27s_Entrenchments_and_The_Drift]; The site is undated (its date is unknown) [SUPPORTED: https://en.wikipedia.org/wiki/King_Lud%27s_Entrenchments_and_The_Drift]; It was thought to be a Saxon boundary ditch [SUPPORTED: https://en.wikipedia.org/wiki/King_Lud%27s_Entrenchments_and_The_Drift]; Aerial photographic work suggests it may belong to a prehistoric boundary system running to the Humber [SUPPORTED: https://en.wikipedia.org/wiki/King_Lud%27s_Entrenchments_and_The_Drift]"}]'::jsonb),
    ('0e3698c6-006c-4161-a8c3-8dfac5bdf2cc'::uuid, 'card_description', 'Built 1700–1550 BC for an obscure 13th Dynasty pharaoh of the turbulent Second Intermediate Period. Every stone of its upper structure was stripped by robbers; only the substructure survives.', 'In southern Dahshur, the Ameny Qemau Pyramid once stood 35 metres high for an obscure king of the 13th Dynasty. Its stone upper structure was robbed; its damaged substructures remain.', 'teaser-card-s012:0e3698c6-006c-4161-a8c3-8dfac5bdf2cc:card_description', 'teaser-card-s012 (teaser-card): teaser card, 183 characters, checked PASS, web-verified VERIFIED', '25570f5a00f56f87a7b385f08b32ade134a63693771c62a0548b8f866fd6ee80|40b6b81e1d2cd0c98929f9e0148a160e720c425554c5e485a5177d2aa123e2a0|40b6b81e1d2cd0c98929f9e0148a160e720c425554c5e485a5177d2aa123e2a0', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "In southern Dahshur, the Ameny Qemau Pyramid once stood 35 metres high for an obscure king of the 13th Dynasty. Its stone upper structure was robbed; its damaged substructures remain."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-002 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the Ameny Qemau Pyramid is in southern Dahshur [S1]; the pyramid originally stood 35 metres high [S3]; it was built for Ameny Qemau, an obscure king [S2]; that king belonged to the 13th Dynasty [S2]; its stone upper structure was robbed [S4]; its damaged substructures remain [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-004 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "The Ameny Qemau Pyramid is an ancient Egyptian pyramid in southern Dahshur, Egypt (central claim: kind of place and location) [SUPPORTED: https://en.wikipedia.org/wiki/Pyramid_of_Ameny_Qemau]; It was built for Ameny Qemau, an obscure king of the 13th Dynasty [SUPPORTED: https://en.wikipedia.org/wiki/Pyramid_of_Ameny_Qemau]; Ameny Qemau was a pharaoh of the 13th Dynasty [SUPPORTED: https://en.wikipedia.org/wiki/Ameny_Qemau]; The pyramid originally stood 35 metres high [SUPPORTED: https://en.wikipedia.org/wiki/Pyramid_of_Ameny_Qemau]; The stone of its upper structure was robbed [SUPPORTED: https://en.wikipedia.org/wiki/Pyramid_of_Ameny_Qemau]; Its damaged substructures remain [SUPPORTED: https://en.wikipedia.org/wiki/Pyramid_of_Ameny_Qemau]"}]'::jsonb),
    ('0ee44ac1-3636-4c0f-ad66-05370f8b0c55'::uuid, 'card_description', 'An ancient town whose monumental stoa and acropolis date to Early Antiquity. Archaeological excavations continue to reveal its layout at this strategic valley position.', 'Vardarski Rid rises on two hills above the Gevgelija Plain, the Vardar River wrapping the town''s northern and eastern edge. Excavations there revealed a monumental stoa and an acropolis.', 'teaser-card-s012:0ee44ac1-3636-4c0f-ad66-05370f8b0c55:card_description', 'teaser-card-s012 (teaser-card): teaser card, 186 characters, checked PASS, web-verified VERIFIED', '3d078c1e06cec3a2bb65103c3faf8743791a9fe515b157be39c8753db2c4c6e2|398dd3f52f96560a623fe4d30de62e7b8db9bca453219a51da6c4538f502c7b0|398dd3f52f96560a623fe4d30de62e7b8db9bca453219a51da6c4538f502c7b0', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Vardarski Rid rises on two hills above the Gevgelija Plain, the Vardar River wrapping the town''s northern and eastern edge. Excavations there revealed a monumental stoa and an acropolis."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-002 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Vardarski Rid lies on two hills [S8]; it rises above the Gevgelija Plain [S5]; it is an ancient town [S1]; the Vardar River surrounds the town''s northern and eastern edge [S6]; excavations revealed a monumental stoa [S2]; excavations revealed an acropolis [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-004 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Vardarski Rid is an archaeological site of an ancient town at Gevgelija, North Macedonia (central claim: kind of place and location) [SUPPORTED: https://en.wikipedia.org/wiki/Vardarski_Rid]; Vardarski Rid consists of two hills [SUPPORTED: https://haemus.org.mk/vardarski-rid/]; It lies above the Gevgelija Plain [SUPPORTED: https://en.wikipedia.org/wiki/Vardarski_Rid]; The Vardar River wraps the ancient town''s northern and eastern edge [SUPPORTED: https://en.wikipedia.org/wiki/Vardarski_Rid]; Excavations there revealed a monumental stoa [SUPPORTED: https://haemus.org.mk/vardarski-rid/]; Excavations there revealed an acropolis [SUPPORTED: https://haemus.org.mk/vardarski-rid/]"}]'::jsonb),
    ('0f113d77-f9a6-4f54-858e-89a99bba03b4'::uuid, 'card_description', 'A 6 km tunnel built by 30,000 workers to partially drain a lake, completed by 52 AD. Emperor Claudius''s drainage project ranks among the grandest engineering feats of antiquity.', 'Under Mount Salviano, 30,000 workmen and slaves cut the Tunnels of Claudius to partially drain the Fucine Lake: a 6 km emissary, the longest tunnel ever built until 1871.', 'teaser-card-s012:0f113d77-f9a6-4f54-858e-89a99bba03b4:card_description', 'teaser-card-s012 (teaser-card): teaser card, 170 characters, checked PASS, web-verified VERIFIED', '0a4d8fd8c02c2d0b0f726d57d08812b09d3bf1f6d7d8f33d378d47477363d409|4e8a52b8ca2403cd4c598e4dc99a627452b837cb8fdf6eb9b2d3bd2cde0c6893|4e8a52b8ca2403cd4c598e4dc99a627452b837cb8fdf6eb9b2d3bd2cde0c6893', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Under Mount Salviano, 30,000 workmen and slaves cut the Tunnels of Claudius to partially drain the Fucine Lake: a 6 km emissary, the longest tunnel ever built until 1871."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-002 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the tunnel runs under Mount Salviano [S4]; 30,000 workmen and slaves built the Tunnels of Claudius [S2]; the tunnels were built to partially drain the Fucine Lake [S1]; the main tunnel is a 6 km-long emissary [S1]; it was the longest tunnel ever built until 1871 [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-004 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "The Tunnels of Claudius are a Roman drainage tunnel (emissary) with service tunnels at the Fucine Lake in Abruzzo, Italy (central claim: kind of place and location) [SUPPORTED: https://en.wikipedia.org/wiki/Tunnels_of_Claudius]; The tunnel runs under Mount Salviano [SUPPORTED: https://en.wikipedia.org/wiki/Tunnels_of_Claudius]; 30,000 workmen and slaves built it [SUPPORTED: https://en.wikipedia.org/wiki/Tunnels_of_Claudius]; It was cut to partially drain the Fucine Lake (in Abruzzo) [SUPPORTED: https://en.wikipedia.org/wiki/Tunnels_of_Claudius]; The emissary is 6 km long [SUPPORTED: https://en.wikipedia.org/wiki/Tunnels_of_Claudius]; It was the longest tunnel ever built until 1871 [SUPPORTED: https://en.wikipedia.org/wiki/Tunnels_of_Claudius]"}]'::jsonb),
    ('0f42edd7-0a93-46bd-a65c-9382e076fac9'::uuid, 'card_description', 'Of particular importance is a substantial complex of what once were religious buildings, dated to the 2nd–1st century BC.', 'Where the eastern and western Prone meet in Shida Kartli, Dedoplis Mindori holds eight temples and two gateways of the 2nd-1st century BC, all built at once to one rectangular plan.', 'teaser-card-s012:0f42edd7-0a93-46bd-a65c-9382e076fac9:card_description', 'teaser-card-s012 (teaser-card): teaser card, 181 characters, checked PASS, web-verified VERIFIED', '09d7e6fa88da2b4a3ddbad76a09c0738700fcdc969afe75f2021921aad3e510a|7ca5cda73159765ba7f0aa9f84135f2e7252e9f35187e720667c021425c1b9d4|7ca5cda73159765ba7f0aa9f84135f2e7252e9f35187e720667c021425c1b9d4', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Where the eastern and western Prone meet in Shida Kartli, Dedoplis Mindori holds eight temples and two gateways of the 2nd-1st century BC, all built at once to one rectangular plan."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-002 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Dedoplis Mindori lies at the confluence of the eastern and western Prone [S1]; it is in Shida Kartli [S1]; the complex has eight temples [S5]; the complex has two gateways [S5]; the complex dates to the 2nd-1st century BC [S3]; its structures were built simultaneously [S5]; they were built to one uniform rectangular plan [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-005 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Dedoplis Mindori is a complex of temples (religious buildings), an archaeological site [SUPPORTED: https://en.wikipedia.org/wiki/Dedoplis_Mindori]; The site lies in Shida Kartli (Georgia) [SUPPORTED: https://en.wikipedia.org/wiki/Dedoplis_Mindori]; The site lies where the eastern and western Prone meet [SUPPORTED: https://en.wikipedia.org/wiki/Dedoplis_Mindori]; The complex holds eight temples [SUPPORTED: https://en.wikipedia.org/wiki/Dedoplis_Mindori]; The complex holds two gateways [SUPPORTED: https://en.wikipedia.org/wiki/Dedoplis_Mindori]; The temples date to the 2nd-1st century BC [SUPPORTED: https://en.wikipedia.org/wiki/Dedoplis_Mindori]; The temples and gateways were all built at once (simultaneously) [SUPPORTED: https://en.wikipedia.org/wiki/Dedoplis_Mindori]; They were built to one rectangular plan [SUPPORTED: https://en.wikipedia.org/wiki/Dedoplis_Mindori]"}]'::jsonb),
    ('0fa0df95-200a-40bf-805d-51a1f530f973'::uuid, 'card_description', 'Shetland broch with outer walls around 4.5 metres thick -- unusually massive even for the form. Walls on the seaward east side still stand over 4 metres high.', 'On a headland of Yell, Shetland, the iron-age Burra Ness Broch keeps an outer wall around 4.5 metres thick and over 4 metres high on its east side, with a ledge inside for an upper floor.', 'teaser-card-s012:0fa0df95-200a-40bf-805d-51a1f530f973:card_description', 'teaser-card-s012 (teaser-card): teaser card, 187 characters, checked PASS, web-verified VERIFIED', '7ba3e542948f2669a897173e482db5d9dc1d230c707e2df8850f87f57b91449e|126209e7edc5f9b452a75f5b678a661c1da23f04c8d28aa741323552d1a40f87|126209e7edc5f9b452a75f5b678a661c1da23f04c8d28aa741323552d1a40f87', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "On a headland of Yell, Shetland, the iron-age Burra Ness Broch keeps an outer wall around 4.5 metres thick and over 4 metres high on its east side, with a ledge inside for an upper floor."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-002 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Burra Ness Broch stands on a headland [S2]; it is on Yell, Shetland [S1]; it is an iron-age broch [S1]; its outer wall is around 4.5 metres thick [S4]; its outer wall stands over 4 metres high on the east side [S4]; inside there is a ledge to support an upper floor [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-005 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Burra Ness Broch is an iron-age broch (a fortified round tower) [SUPPORTED: https://en.wikipedia.org/wiki/Burra_Ness_Broch]; It is located on Yell, Shetland [SUPPORTED: https://en.wikipedia.org/wiki/Burra_Ness_Broch]; It stands on a headland [SUPPORTED: https://en.wikipedia.org/wiki/Burra_Ness_Broch]; The outer wall is around 4.5 metres thick [SUPPORTED: https://en.wikipedia.org/wiki/Burra_Ness_Broch]; The outer wall stands over 4 metres high on the east side [SUPPORTED: https://en.wikipedia.org/wiki/Burra_Ness_Broch]; Inside there is a ledge (scarcement) that supported an upper floor [SUPPORTED: https://en.wikipedia.org/wiki/Burra_Ness_Broch]"}]'::jsonb),
    ('1374c196-3e09-44d3-b2a8-ac326f6bd14c'::uuid, 'card_description', 'A Bronze Age stone circle near Corfe Castle, hidden in dense woodland. Ten surviving gritstone boulders form an arc suggesting an original oval of ~26 m — Dorset''s second-largest stone circle.', 'In a dense wood on the Isle of Purbeck remain the sandstone boulders of Rempstone Stone Circle, its southern half destroyed. In 1957 ploughing revealed a possible avenue leading to it.', 'teaser-card-s012:1374c196-3e09-44d3-b2a8-ac326f6bd14c:card_description', 'teaser-card-s012 (teaser-card): teaser card, 184 characters, checked PASS, web-verified VERIFIED', 'f4b75d4ff0bba2584e1402a7fd3e532ea4e5c19bb96320991f792a2b67a71957|0327d3f12f1eeaa491546af9c437f7adccc19a5a9cf305eda2a606fdd4ae219f|0327d3f12f1eeaa491546af9c437f7adccc19a5a9cf305eda2a606fdd4ae219f', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "In a dense wood on the Isle of Purbeck remain the sandstone boulders of Rempstone Stone Circle, its southern half destroyed. In 1957 ploughing revealed a possible avenue leading to it."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-002 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Rempstone Stone Circle lies in a dense wood [S5]; it is on the Isle of Purbeck [S1]; its stones are sandstone boulders [S6]; stones of the circle remain [S3]; the southern half of the circle has been destroyed [S3]; in 1957 ploughing revealed a possible avenue leading to the circle [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-005 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Rempstone Stone Circle is a stone circle on the Isle of Purbeck (England) [SUPPORTED: https://en.wikipedia.org/wiki/Rempstone_Stone_Circle]; The circle lies in a dense wood [SUPPORTED: https://en.wikipedia.org/wiki/Rempstone_Stone_Circle]; Its remaining stones are sandstone boulders [SUPPORTED: https://en.wikipedia.org/wiki/Rempstone_Stone_Circle]; The southern half of the circle is destroyed [SUPPORTED, no proving quote: https://en.wikipedia.org/wiki/Rempstone_Stone_Circle]; In 1957 something was revealed at the site (the year of the avenue discovery) [SUPPORTED: https://en.wikipedia.org/wiki/Rempstone_Stone_Circle]; Ploughing revealed the avenue [SUPPORTED: https://en.wikipedia.org/wiki/Rempstone_Stone_Circle]; It was a possible avenue leading to the circle [SUPPORTED: https://en.wikipedia.org/wiki/Rempstone_Stone_Circle]"}]'::jsonb),
    ('14f64a8d-97b4-4d86-9b1f-187a126febb8'::uuid, 'card_description', 'A Roman municipium covering 3 square kilometres with a square ground plan, founded in the 1st century AD. The site was closed for protection after recent excavations.', 'The Romans noticed a crossing of the Mura river and built a military stronghold to watch it. Halikan grew into some kind of commercial centre; an altar to Jupiter is among its finds.', 'teaser-card-s012:14f64a8d-97b4-4d86-9b1f-187a126febb8:card_description', 'teaser-card-s012 (teaser-card): teaser card, 182 characters, checked PASS, web-verified VERIFIED', '31593d9576d7d1f8e68b1f3944b972eb2401f8b4bcd96ad616526a67a1d2f5d3|bae14612c3eecb30c3271dbe1ed71e4074a83092512aa528715a769842b87b0b|bae14612c3eecb30c3271dbe1ed71e4074a83092512aa528715a769842b87b0b', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-rewrite-v-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "The Romans noticed a crossing of the Mura river and built a military stronghold to watch it. Halikan grew into some kind of commercial centre; an altar to Jupiter is among its finds."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-v-001 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the Romans noticed a crossing of the Mura river [S3, S4]; the Romans built (established) a military stronghold [S4]; the stronghold was to watch (monitor) the river crossing [S4]; Halikan grew into some kind of commercial centre [S5]; an altar dedicated to Jupiter is among the finds at Halikan [S8]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify2-001 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Halikan is an ancient Roman settlement (municipium) in Croatia, at the Mura river [SUPPORTED: https://en.wikipedia.org/wiki/Halikan]; There was a crossing of the Mura river that the Romans noticed [SUPPORTED: https://en.wikipedia.org/wiki/Halikan]; The Romans built a military stronghold to watch the river crossing [SUPPORTED: https://en.wikipedia.org/wiki/Halikan]; Halikan grew into some kind of commercial centre [SUPPORTED: https://en.wikipedia.org/wiki/Halikan]; An altar to Jupiter is among the finds of Halikan [SUPPORTED: https://en.wikipedia.org/wiki/Halikan]; The altar (ara) found at Halikan was an altar, dedicated to Jupiter by a Roman benefactor [SUPPORTED: https://en.wikipedia.org/wiki/Halikan]"}]'::jsonb),
    ('1531d4a1-bb24-4727-9b25-f2089088acaf'::uuid, 'card_description', 'A Roman legionary fortress and Pannonian fleet headquarters from 50 AD, later capital of a province. It lies halfway between modern Vienna and Bratislava on the Danube.', 'Where the Amber Road crossed the Danube, Carnuntum traded amber bound for Italy. In 308 the Emperor emeritus Diocletian chaired a meeting here with his co-emperors Maximian and Galerius.', 'teaser-card-s012:1531d4a1-bb24-4727-9b25-f2089088acaf:card_description', 'teaser-card-s012 (teaser-card): teaser card, 186 characters, checked PASS, web-verified VERIFIED', '2bd3f3e93c9ddaca2f58e7a34aecffe1fbf36d3f178f75249377d586eff763aa|35817aa4c7f472de840256a557f4d9ce8d57029fab9caccdae2e1614cde413a8|35817aa4c7f472de840256a557f4d9ce8d57029fab9caccdae2e1614cde413a8', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Where the Amber Road crossed the Danube, Carnuntum traded amber bound for Italy. In 308 the Emperor emeritus Diocletian chaired a meeting here with his co-emperors Maximian and Galerius."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-002 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the Amber Road crossed the Danube at Carnuntum [S4]; Carnuntum was a trading centre for amber that was sold in Italy [S4]; in 308 a meeting was held at Carnuntum [S7]; the Emperor emeritus Diocletian chaired that meeting [S7]; his co-emperors Maximian and Galerius took part [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-005 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Carnuntum was a Roman city and legionary fortress (an ancient town, not a mere find spot) [SUPPORTED: https://en.wikipedia.org/wiki/Carnuntum]; Carnuntum lies on the Danube in Austria (Lower Austria) [SUPPORTED: https://en.wikipedia.org/wiki/Carnuntum]; The Amber Road crossed the Danube at Carnuntum [SUPPORTED: https://en.wikipedia.org/wiki/Carnuntum]; Carnuntum traded amber [SUPPORTED: https://en.wikipedia.org/wiki/Carnuntum]; The amber was bound for Italy (sold in Italy) [SUPPORTED: https://en.wikipedia.org/wiki/Carnuntum]; In 308 a meeting (the Conference of Carnuntum) took place at Carnuntum [SUPPORTED: https://en.wikipedia.org/wiki/Carnuntum]; Diocletian, by then Emperor emeritus, chaired the meeting [SUPPORTED: https://en.wikipedia.org/wiki/Carnuntum]; The meeting was with his co-emperors Maximian and Galerius [SUPPORTED: https://en.wikipedia.org/wiki/Carnuntum]"}]'::jsonb),
    ('163d97cd-99ba-45d3-b059-83c3e0249c3d'::uuid, 'card_description', 'A 3rd-2nd century BC burial mound with Saka warrior graves. The Saka were horse-mounted nomads whose gold ornaments rival Scythian craftsmanship.', 'In 1999 archaeologists opened the Araltobe Kurgan in Kazakhstan and found a Golden Man, long swords with mushroom-shaped pommels and about 400 gold objects in the tomb.', 'teaser-card-s012:163d97cd-99ba-45d3-b059-83c3e0249c3d:card_description', 'teaser-card-s012 (teaser-card): teaser card, 168 characters, checked PASS, web-verified VERIFIED', '6f5d061329326717e34ea8ac943b89f2033068aac1c752608a6c570e1e2c7d3f|a37fc9e59eadc60e72f0def3d2201645540c90f1740360d89b19f2240c903601|a37fc9e59eadc60e72f0def3d2201645540c90f1740360d89b19f2240c903601', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "In 1999 archaeologists opened the Araltobe Kurgan in Kazakhstan and found a Golden Man, long swords with mushroom-shaped pommels and about 400 gold objects in the tomb."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-002 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "archaeologists excavated the Araltobe Kurgan in 1999 [S2]; the kurgan is in Kazakhstan [S1]; they found the remains of a Golden Man [S3]; they found long swords with mushroom-shaped pommels [S4]; about 400 gold objects were found in the tomb [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-006 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "The Araltobe Kurgan is a tomb: a kurgan (burial mound) burial ground [SUPPORTED: https://en.wikipedia.org/wiki/Araltobe_kurgan]; The Araltobe Kurgan is in Kazakhstan [SUPPORTED: https://en.wikipedia.org/wiki/Araltobe_kurgan]; Archaeologists excavated (opened) the kurgan in 1999 [SUPPORTED: https://en.wikipedia.org/wiki/Araltobe_kurgan]; The archaeologists found the remains of a Golden Man in the kurgan [SUPPORTED: https://en.wikipedia.org/wiki/Araltobe_kurgan]; Long swords with mushroom-shaped pommels were found in the excavation [SUPPORTED: https://en.wikipedia.org/wiki/Araltobe_kurgan]; About 400 gold objects were found in the tomb [SUPPORTED: https://en.wikipedia.org/wiki/Araltobe_kurgan]"}]'::jsonb),
    ('16419886-7d47-4007-86ae-2fef6dd1fa38'::uuid, 'card_description', 'The Thul Hairo Khan is a Buddhist stupa, built possibly between the 5th and 7th centuries CE near the modern-day town of Johi, in Sindh.', 'Near Johi in Sindh rises Thul Hairo Khan, a Buddhist stupa 50 feet high of mud and baked bricks, built possibly between the 5th and 7th centuries CE, an arched tunnel at its foot.', 'teaser-card-s012:16419886-7d47-4007-86ae-2fef6dd1fa38:card_description', 'teaser-card-s012 (teaser-card): teaser card, 179 characters, checked PASS, web-verified VERIFIED', '345f44e6bc4c026946f933508926992a0cc8b3b0f9f65bd500ae186c5fec1e27|27c637013e5bb796b2f88aa44e5232102790ec242e71d790704ce609a77d9eab|27c637013e5bb796b2f88aa44e5232102790ec242e71d790704ce609a77d9eab', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Near Johi in Sindh rises Thul Hairo Khan, a Buddhist stupa 50 feet high of mud and baked bricks, built possibly between the 5th and 7th centuries CE, an arched tunnel at its foot."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-002 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Thul Hairo Khan is near Johi [S1]; it is in Sindh [S1]; it is a Buddhist stupa [S1]; the stupa is 50 feet high [S3]; it is built of mud (bricks and mortar) and baked bricks [S2]; it was built possibly between the 5th and 7th centuries CE [S1]; an arched tunnel runs through it at ground level [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-006 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Thul Hairo Khan is a Buddhist stupa [SUPPORTED: https://en.wikipedia.org/wiki/Thul_Hairo_Khan]; It stands near the town of Johi [SUPPORTED: https://en.wikipedia.org/wiki/Thul_Hairo_Khan]; It stands in Sindh (Pakistan) [SUPPORTED: https://en.wikipedia.org/wiki/Thul_Hairo_Khan]; The stupa is 50 feet high [SUPPORTED: https://en.wikipedia.org/wiki/Thul_Hairo_Khan]; It is built of mud (mud bricks) [SUPPORTED: https://en.wikipedia.org/wiki/Thul_Hairo_Khan]; It is built of baked bricks [SUPPORTED: https://en.wikipedia.org/wiki/Thul_Hairo_Khan]; It was built possibly between the 5th and 7th centuries CE [SUPPORTED: https://en.wikipedia.org/wiki/Thul_Hairo_Khan]; The stupa has an arched tunnel at its foot (at ground level) [SUPPORTED: https://en.wikipedia.org/wiki/Thul_Hairo_Khan]"}]'::jsonb),
    ('16bc7c0d-247d-4de5-960c-d870236b7bb1'::uuid, 'card_description', 'A Maya city whose Temple of the Feathered Serpent blends Teotihuacan and Maya artistic styles. An underground observatory tracked the sun''s zenith passage twice yearly.', 'In Morelos, Xochicalco keeps three ballcourts, an unusual row of circular altars and a cave with steps carved down into it. Around 900 CE the city was burned and destroyed.', 'teaser-card-s012:16bc7c0d-247d-4de5-960c-d870236b7bb1:card_description', 'teaser-card-s012 (teaser-card): teaser card, 172 characters, checked PASS, web-verified VERIFIED', 'c158cb33ddc5c9756bae7ac1849acc173626fe7f66dd07f285d7d0f47269c4a3|356ea432eeeab3679b021d7b25337a3aab818b6e5a204dd0d77b1814d2f29500|356ea432eeeab3679b021d7b25337a3aab818b6e5a204dd0d77b1814d2f29500', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "In Morelos, Xochicalco keeps three ballcourts, an unusual row of circular altars and a cave with steps carved down into it. Around 900 CE the city was burned and destroyed."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-002 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Xochicalco is in Morelos [S1]; the site has three ballcourts [S5]; the site has an unusual row of circular altars [S5]; the site has a cave with steps carved down into it [S5]; around 900 CE the city was burned and destroyed [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-006 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Xochicalco is a pre-Columbian archaeological site (a city) in the Mexican state of Morelos [SUPPORTED: https://en.wikipedia.org/wiki/Xochicalco]; Xochicalco has three ballcourts [SUPPORTED: https://en.wikipedia.org/wiki/Xochicalco]; Xochicalco has an unusual row of circular altars [SUPPORTED: https://en.wikipedia.org/wiki/Xochicalco]; Xochicalco has a cave with steps carved down into it [SUPPORTED: https://en.wikipedia.org/wiki/Xochicalco]; Around 900 CE the city of Xochicalco was burned and destroyed [SUPPORTED: https://en.wikipedia.org/wiki/Xochicalco]"}]'::jsonb),
    ('16bdc3b7-0e3b-4c6f-9313-6988d76fa673'::uuid, 'card_description', 'A 5,505 m volcano formed during four stages of Pleistocene volcanic activity. Ancient peoples lived in the shadow of a mountain that could erupt again.', 'The Inca made human sacrifices on Sara Sara, a 5,505-metre volcano. In 1996, near its summit, archaeologists recovered a mummy nicknamed Sarita who appears to be a 15-year old girl.', 'teaser-card-s012:16bdc3b7-0e3b-4c6f-9313-6988d76fa673:card_description', 'teaser-card-s012 (teaser-card): teaser card, 181 characters, checked PASS, web-verified VERIFIED', 'd3f64b5a2cfc367c1b4088fe6494b6f17481f4a61b2072858006807c21340233|78a08962fc38a1f27bcf155e5733c9a5d0bcd45a29aeee6515e9a9210718ae90|78a08962fc38a1f27bcf155e5733c9a5d0bcd45a29aeee6515e9a9210718ae90', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "The Inca made human sacrifices on Sara Sara, a 5,505-metre volcano. In 1996, near its summit, archaeologists recovered a mummy nicknamed Sarita who appears to be a 15-year old girl."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-002 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the Inca performed human sacrifices on Sara Sara [S3]; Sara Sara is a volcano [S1]; it is 5,505 metres high [S1]; in 1996 archaeologists recovered a body near its summit [S6]; the mummy was nicknamed Sarita [S7]; the mummy appears to be a 15-year-old girl [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-006 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Sara Sara is a volcano (in Peru) [SUPPORTED: https://en.wikipedia.org/wiki/Sara_Sara]; Sara Sara is 5,505 metres high [SUPPORTED: https://en.wikipedia.org/wiki/Sara_Sara]; The Inca made human sacrifices on Sara Sara [SUPPORTED: https://en.wikipedia.org/wiki/Sara_Sara]; In 1996 archaeologists recovered a body (mummy) at Sara Sara [SUPPORTED: https://en.wikipedia.org/wiki/Sara_Sara]; The body was found near the summit [SUPPORTED: https://en.wikipedia.org/wiki/Sara_Sara]; The mummy was nicknamed Sarita [SUPPORTED: https://en.wikipedia.org/wiki/Sara_Sara]; The mummy appears to be a 15-year old girl [SUPPORTED: https://en.wikipedia.org/wiki/Sara_Sara]"}]'::jsonb),
    ('171c0658-fbad-43fd-9764-fa7b37c5ba28'::uuid, 'card_description', 'Neolithic dolmen near St Keverne dated to 3300 BC, its two orthostats supporting a capstone with possible cup-mark depressions. The enclosed chamber measures roughly 4 by 2 m.', 'Near a hilltop overlooking Goonhilly Downs, upright stones hold the capstone of the Three Brothers of Grugith, a Neolithic dolmen; its hollows may be cup marks, or may be natural.', 'teaser-card-s012:171c0658-fbad-43fd-9764-fa7b37c5ba28:card_description', 'teaser-card-s012 (teaser-card): teaser card, 179 characters, checked PASS, web-verified VERIFIED', '0dca7223fb3e25cfe5a4d39f9b6dd6bd669e9087a8de5a9b3b586f83e84a4b32|e0ee99ba5f958a6f4ba33208ccc0387d9761605fd86a489103ced4bc7d12ae8f|e0ee99ba5f958a6f4ba33208ccc0387d9761605fd86a489103ced4bc7d12ae8f', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Near a hilltop overlooking Goonhilly Downs, upright stones hold the capstone of the Three Brothers of Grugith, a Neolithic dolmen; its hollows may be cup marks, or may be natural."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-002 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the monument is near the summit of a hill [S3]; the hill overlooks Goonhilly Downs [S3]; upright stones (orthostats) support the capstone [S4]; the Three Brothers of Grugith is a dolmen [S1]; the dolmen is Neolithic [S1]; depressions on the capstone may be cup marks or may be natural [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-006 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "The Three Brothers of Grugith is a dolmen (a prehistoric monument) near St Keverne in Cornwall, England [SUPPORTED: https://en.wikipedia.org/wiki/Three_Brothers_of_Grugith]; The dolmen is Neolithic [SUPPORTED: https://en.wikipedia.org/wiki/Three_Brothers_of_Grugith]; It lies near the summit of a hilltop overlooking Goonhilly Downs [SUPPORTED: https://en.wikipedia.org/wiki/Three_Brothers_of_Grugith]; Upright stones (two orthostats) support the capstone [SUPPORTED: https://en.wikipedia.org/wiki/Three_Brothers_of_Grugith]; Hollows (depressions) on the capstone may be cup marks [SUPPORTED: https://en.wikipedia.org/wiki/Three_Brothers_of_Grugith]; The hollows on the capstone may instead be natural [SUPPORTED: https://en.wikipedia.org/wiki/Three_Brothers_of_Grugith]"}]'::jsonb),
    ('1724deb2-8bac-4a38-971b-4d1542745e0b'::uuid, 'card_description', 'Eight-metre-diameter Bronze Age entrance grave on the Isles of Scilly, set on a low platform 12 metres across. Directly below lie the remains of the Iron Age village of Halangy Down.', 'On a steep slope of St Mary''s, a roofless entrance leads past a jamb into the burial chamber of Bant''s Carn, a Bronze Age entrance grave roofed by four large capstones.', 'teaser-card-s012:1724deb2-8bac-4a38-971b-4d1542745e0b:card_description', 'teaser-card-s012 (teaser-card): teaser card, 168 characters, checked PASS, web-verified VERIFIED', '26e0d995b86b2a0b9a25b98c2be52ffc5614b0f5cc3c2f1708b4903f2a144a5a|2d1cf315a54942493fb9001d1e34cb8d4b20d1d9fcdab08640474f034a49f94b|2d1cf315a54942493fb9001d1e34cb8d4b20d1d9fcdab08640474f034a49f94b', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-003", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "On a steep slope of St Mary''s, a roofless entrance leads past a jamb into the burial chamber of Bant''s Carn, a Bronze Age entrance grave roofed by four large capstones."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-003 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the site lies on a steep slope [S1]; the site is on St Mary''s [S1]; the entrance has no roof [S4]; a jamb separates the entrance from the burial chamber [S5]; Bant''s Carn is a Bronze Age entrance grave [S1]; the burial chamber is roofed by four large capstones [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-007 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Bant''s Carn is a Bronze Age entrance grave, a tomb, on St Mary''s in the Isles of Scilly, England [SUPPORTED: https://www.english-heritage.org.uk/visit/places/bants-carn-burial-chamber-and-halangy-down-ancient-village/history/]; It stands on a steep slope of St Mary''s [SUPPORTED: https://en.wikipedia.org/wiki/Bant%27s_Carn]; Its entrance passage is roofless [SUPPORTED: https://www.english-heritage.org.uk/visit/places/bants-carn-burial-chamber-and-halangy-down-ancient-village/history/]; The entrance passage leads into a burial chamber [SUPPORTED: https://www.english-heritage.org.uk/visit/places/bants-carn-burial-chamber-and-halangy-down-ancient-village/history/]; A jamb separates the entrance from the burial chamber [SUPPORTED: https://en.wikipedia.org/wiki/Bant%27s_Carn]; The burial chamber is roofed by four large capstones [SUPPORTED: https://www.english-heritage.org.uk/visit/places/bants-carn-burial-chamber-and-halangy-down-ancient-village/history/]"}]'::jsonb),
    ('17483f6c-6a12-4652-83e1-e0a2f6665429'::uuid, 'card_description', '3rd-century BC mountain site near Paraćin. A chest found at its peak yielded 14 sets of weapons, harness gear, jewellery, and clothing accessories characteristic of Dacian and Scordisci knights.', 'On Veliki Vetren, the highest peak of Juhor, findings include some 14 sets of weapons, harness gear and jewelry characteristic of knights of Dacian and Scordisci origin.', 'teaser-card-s012:17483f6c-6a12-4652-83e1-e0a2f6665429:card_description', 'teaser-card-s012 (teaser-card): teaser card, 169 characters, checked PASS, web-verified VERIFIED', 'f5df257b31a2265143ebe60fda30e1a900881683d71d12654d928b2f4ed3bc63|bd76873fbabb17053e5a5dd9d7f62644474028d591a8ea197652be7f7a6fbde7|bd76873fbabb17053e5a5dd9d7f62644474028d591a8ea197652be7f7a6fbde7', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-rewrite-v-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "On Veliki Vetren, the highest peak of Juhor, findings include some 14 sets of weapons, harness gear and jewelry characteristic of knights of Dacian and Scordisci origin."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-v-001 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Veliki Vetren is the highest peak of Juhor [S2]; findings on Veliki Vetren include some 14 sets of weapons [S4]; the findings include harness gear [S4]; the findings include jewelry [S4]; the finds are characteristic of knights of Dacian and Scordisci origin [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify2-001 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Juhor is a mountain in central Serbia [SUPPORTED: https://en.wikipedia.org/wiki/Juhor]; Veliki Vetren is the highest peak of Juhor [SUPPORTED: https://en.wikipedia.org/wiki/Juhor]; Findings at Veliki Vetren include some 14 sets of weapons, harness gear and jewelry [SUPPORTED: https://en.wikipedia.org/wiki/Juhor]; The findings are characteristic of knights of Dacian origin [SUPPORTED: https://en.wikipedia.org/wiki/Juhor]; The findings are characteristic of knights of Scordisci origin [SUPPORTED: https://en.wikipedia.org/wiki/Juhor]"}]'::jsonb),
    ('1825d8d7-d419-457c-b575-94478e05c127'::uuid, 'card_description', 'Lucanian settlers occupied this site in the 6th century BC; the Romans founded a formal city here in the 3rd century BC. Its forum, theatre, and amphitheatre survive in excellent condition.', 'Under the walls of Grumentum, an ancient Roman city in the centre of Lucania, the Carthaginian general Hanno was defeated in 215 BC; in 207 BC Hannibal made it his headquarters.', 'teaser-card-s012:1825d8d7-d419-457c-b575-94478e05c127:card_description', 'teaser-card-s012 (teaser-card): teaser card, 177 characters, checked PASS, web-verified VERIFIED', 'c548c54a3f5793a3a501acff12099b2c29aa1b03670a3be79c0daf5bdd4e3af6|c363413dbe6e01ca98d4f2752b06ab3fd1fea801cee0eec9af1a157425adc456|c363413dbe6e01ca98d4f2752b06ab3fd1fea801cee0eec9af1a157425adc456', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-003", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Under the walls of Grumentum, an ancient Roman city in the centre of Lucania, the Carthaginian general Hanno was defeated in 215 BC; in 207 BC Hannibal made it his headquarters."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-003 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Grumentum was an ancient Roman city [S1]; it lay in the centre of Lucania [S1]; the Carthaginian general Hanno was defeated under its walls [S5]; Hanno''s defeat was in 215 BC [S5]; in 207 BC Hannibal made the city his headquarters [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-007 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Grumentum is an ancient Roman city in the centre of Lucania [SUPPORTED: https://en.wikipedia.org/wiki/Grumentum]; The Carthaginian general Hanno was defeated at Grumentum [SUPPORTED: https://www.perseus.tufts.edu/hopper/text?doc=Liv.+23.37]; Hanno was defeated under the walls of Grumentum [SUPPORTED: https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.04.0064:entry=grumentum-geo]; Hanno was defeated at Grumentum in 215 BC [SUPPORTED: https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.04.0064:entry=grumentum-geo]; Hannibal was at Grumentum in 207 BC [SUPPORTED: https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.04.0064:entry=grumentum-geo]; In 207 BC Hannibal made Grumentum his headquarters [SUPPORTED: https://en.wikipedia.org/wiki/Grumentum]"}]'::jsonb),
    ('18c1c7b1-c7b0-415d-b390-f862c4924120'::uuid, 'card_description', 'Built 3400–2400 BC entirely of rounded boulders — not quarried stone — this Northumberland long cairn measures 60 by 14 meters. Very few long cairns survive in the county.', 'In Kielder Forest lies the Devil''s Lapful, a Neolithic long cairn of rounded boulders, 60 by 14 metres and 2 metres high, one of few surviving long cairns in Northumberland.', 'teaser-card-s012:18c1c7b1-c7b0-415d-b390-f862c4924120:card_description', 'teaser-card-s012 (teaser-card): teaser card, 173 characters, checked PASS, web-verified VERIFIED', '3311df5fc790ad84ea592957724195c9bb41af4c1a94008cfa986339f5dccf92|d12f0449b69799e1d2cbb691bc8699e4e26ea7f35b07084912d4d90231303bdc|d12f0449b69799e1d2cbb691bc8699e4e26ea7f35b07084912d4d90231303bdc', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-003", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "In Kielder Forest lies the Devil''s Lapful, a Neolithic long cairn of rounded boulders, 60 by 14 metres and 2 metres high, one of few surviving long cairns in Northumberland."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-003 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the site lies in Kielder Forest [S1]; Devil''s Lapful is a Neolithic long cairn [S2]; it is built of rounded boulders [S5]; it measures 60 by 14 metres [S5]; it is 2 metres high [S5]; it is one of few surviving long cairns in Northumberland [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-007 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Devil''s Lapful is a Neolithic long cairn [SUPPORTED: https://en.wikipedia.org/wiki/Devil%27s_Lapful]; It lies in Kielder Forest, Northumberland [SUPPORTED: https://en.wikipedia.org/wiki/Devil%27s_Lapful]; The cairn is built of rounded boulders [SUPPORTED: https://keystothepast.info/search-records/results-of-search/results-of-search-2/site-details/?PRN=N6262]; The cairn measures 60 by 14 metres [SUPPORTED: https://keystothepast.info/search-records/results-of-search/results-of-search-2/site-details/?PRN=N6262]; The cairn is 2 metres high [SUPPORTED: https://keystothepast.info/search-records/results-of-search/results-of-search-2/site-details/?PRN=N6262]; It is one of few surviving long cairns in Northumberland [SUPPORTED: https://en.wikipedia.org/wiki/Devil%27s_Lapful]"}]'::jsonb),
    ('19dcdb91-8d2c-43a7-acae-e7d709c576fe'::uuid, 'card_description', 'A Neolithic henge 90 metres in diameter, 400 metres from Mayburgh Henge. Named after King Arthur, though it predates the legend by thousands of years.', 'A sketch from around 1664 shows two standing stones at the northwest entrance of King Arthur''s Round Table, a Neolithic henge in Cumbria. By 1725 they had disappeared.', 'teaser-card-s012:19dcdb91-8d2c-43a7-acae-e7d709c576fe:card_description', 'teaser-card-s012 (teaser-card): teaser card, 167 characters, checked PASS, web-verified VERIFIED', 'cb5a50e779a5ed7b99a64185eaf333d81d33f1560a68fba9dead872d96c3b1f4|95528151830563bd7c6fdcfdd53fd70001e25eb135e9e5aa2ea8d63d0731e268|95528151830563bd7c6fdcfdd53fd70001e25eb135e9e5aa2ea8d63d0731e268', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-003", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "A sketch from around 1664 shows two standing stones at the northwest entrance of King Arthur''s Round Table, a Neolithic henge in Cumbria. By 1725 they had disappeared."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-003 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "a sketch was made around 1664 [S5]; the sketch shows two standing stones at the northwest entrance [S5]; King Arthur''s Round Table is a Neolithic henge [S1]; it is in Cumbria [S1]; by 1725 the two stones had disappeared [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-007 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "King Arthur''s Round Table is a Neolithic henge [SUPPORTED: https://en.wikipedia.org/wiki/King_Arthur%27s_Round_Table]; The henge is in Cumbria [SUPPORTED: https://en.wikipedia.org/wiki/King_Arthur%27s_Round_Table]; A sketch from around 1664 shows the henge [SUPPORTED: https://en.wikipedia.org/wiki/King_Arthur%27s_Round_Table]; The sketch shows two standing stones [SUPPORTED: https://en.wikipedia.org/wiki/King_Arthur%27s_Round_Table]; The two standing stones stood at the northwest entrance [SUPPORTED: https://en.wikipedia.org/wiki/King_Arthur%27s_Round_Table]; By 1725 the stones had disappeared [SUPPORTED: https://en.wikipedia.org/wiki/King_Arthur%27s_Round_Table]"}]'::jsonb),
    ('1b3a3297-9a51-4abf-8528-f194ef9161a0'::uuid, 'card_description', 'A rock-cut funerary complex from ~50 AD so grand it was mistaken for royal tombs. It actually belonged to Queen Helena of Adiabene, a convert to Judaism.', 'In East Jerusalem a hewn staircase 9 metres wide descends to the Tombs of the Kings. Among the sarcophagi found there, one bore the Hebrew inscription Queen Tzaddah.', 'teaser-card-s012:1b3a3297-9a51-4abf-8528-f194ef9161a0:card_description', 'teaser-card-s012 (teaser-card): teaser card, 165 characters, checked PASS, web-verified VERIFIED', 'a92c91589c52eccdfd416308aeabfeec20359e0811ba26e06b5b9406db943820|84a558bda741a25f0b4287804a7de8442d9b44c35da54817deac6a390b2e2cae|84a558bda741a25f0b4287804a7de8442d9b44c35da54817deac6a390b2e2cae', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-003", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "In East Jerusalem a hewn staircase 9 metres wide descends to the Tombs of the Kings. Among the sarcophagi found there, one bore the Hebrew inscription Queen Tzaddah."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-003 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the Tombs of the Kings are in East Jerusalem [S1]; a hewn staircase descends into the tomb complex [S3]; the staircase is 9 metres wide [S3]; sarcophagi were found at the tomb [S7]; one sarcophagus bore the Hebrew inscription Queen Tzaddah [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-008 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "The Tombs of the Kings are a rock-cut funerary complex, that is a tomb complex (the kind of place) [SUPPORTED: https://en.wikipedia.org/wiki/Tombs_of_the_Kings_(Jerusalem)]; The Tombs of the Kings lie in East Jerusalem [SUPPORTED: https://en.wikipedia.org/wiki/Tombs_of_the_Kings_(Jerusalem)]; The tombs have a hewn (rock-cut) staircase [SUPPORTED: https://en.wikipedia.org/wiki/Tombs_of_the_Kings_(Jerusalem)]; The hewn staircase is 9 metres wide [SUPPORTED: https://en.wikipedia.org/wiki/Tombs_of_the_Kings_(Jerusalem)]; The staircase descends to the tombs (into a carved courtyard in front of the tomb portal) [SUPPORTED: https://en.wikipedia.org/wiki/Tombs_of_the_Kings_(Jerusalem)]; Sarcophagi were found in the tombs [SUPPORTED: https://en.wikipedia.org/wiki/Tombs_of_the_Kings_(Jerusalem)]; One of the sarcophagi bore the Hebrew inscription Queen Tzaddah [SUPPORTED: https://en.wikipedia.org/wiki/Tombs_of_the_Kings_(Jerusalem)]"}]'::jsonb),
    ('1b8b5fd4-d6b2-4ae0-9783-6e4e39a1314f'::uuid, 'card_description', 'Spur fort in Somerset with steep drops on the north, east, and south. The bank reaches 1.6 metres high; the ditch drops 2 metres below -- small in area but well-chosen for its natural advantages.', 'On a spur near Selworthy sits Bury Castle, an Iron Age hillfort whose main enclosure has a single rampart and ditch, with steep drops on the north, east and south sides.', 'teaser-card-s012:1b8b5fd4-d6b2-4ae0-9783-6e4e39a1314f:card_description', 'teaser-card-s012 (teaser-card): teaser card, 169 characters, checked PASS, web-verified VERIFIED', '321d88329a26ee86a49dedb7f269a9d8f6b20740d87001fd8ecefcc362ec41ac|204ea892f84cbb0b8f9de7ae6b1ea8a92cd7160562ed75a88d0290d75e8c8050|204ea892f84cbb0b8f9de7ae6b1ea8a92cd7160562ed75a88d0290d75e8c8050', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-003", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "On a spur near Selworthy sits Bury Castle, an Iron Age hillfort whose main enclosure has a single rampart and ditch, with steep drops on the north, east and south sides."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-003 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Bury Castle sits on a spur of land [S2]; it is near Selworthy [S1]; Bury Castle is an Iron Age hillfort [S1]; its main enclosure has a single rampart and ditch [S4]; there are steep drops on the north, east and south sides [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-008 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Bury Castle is a hillfort (the kind of place), in Somerset, England [SUPPORTED: https://en.wikipedia.org/wiki/Bury_Castle,_Selworthy]; Bury Castle dates to the Iron Age [SUPPORTED: https://en.wikipedia.org/wiki/Bury_Castle,_Selworthy]; Bury Castle is near Selworthy [SUPPORTED: https://en.wikipedia.org/wiki/Bury_Castle,_Selworthy]; Bury Castle sits on a spur of land [SUPPORTED: https://en.wikipedia.org/wiki/Bury_Castle,_Selworthy]; The main enclosure has a single rampart and ditch [SUPPORTED: https://en.wikipedia.org/wiki/Bury_Castle,_Selworthy]; There are steep drops on the north, east and south sides of the main enclosure [SUPPORTED: https://en.wikipedia.org/wiki/Bury_Castle,_Selworthy]"}]'::jsonb),
    ('1baa447b-94b2-4081-9a54-f699005efcc5'::uuid, 'card_description', 'Named for the chieftain Caradoc who led resistance against Rome. Two separate Shropshire hillforts bear his name -- historians have never agreed which was the site of his final stand.', 'Rising sharply out of the Stretton Gap, Caer Caradoc tops a narrow whaleback ridge in Shropshire, its summit holding an Iron Age or late Bronze Age hill fort: Caradog''s fort.', 'teaser-card-s012:1baa447b-94b2-4081-9a54-f699005efcc5:card_description', 'teaser-card-s012 (teaser-card): teaser card, 174 characters, checked PASS, web-verified VERIFIED', '37b7bff34a005bc5b40722b403aa2c045df2bd61d9ad6025f385c9a2fd0c5cf9|aad2abd7f5bdbd8ce4e72e17e2b72421092a142b611739a1fe3ffe6ee213bea2|aad2abd7f5bdbd8ce4e72e17e2b72421092a142b611739a1fe3ffe6ee213bea2', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-003", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Rising sharply out of the Stretton Gap, Caer Caradoc tops a narrow whaleback ridge in Shropshire, its summit holding an Iron Age or late Bronze Age hill fort: Caradog''s fort."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-003 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Caer Caradoc rises sharply out of the Stretton Gap [S2]; it is the highest point of a narrow whaleback ridge [S3]; it is in Shropshire [S1]; its summit has an Iron Age or late Bronze Age hill fort [S4]; the name means Caradog''s fort, after the hill fort [S1, S5]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-008 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Caer Caradoc is a hill in Shropshire, England, with a hill fort on its summit (the central claim) [SUPPORTED: https://en.wikipedia.org/wiki/Caer_Caradoc]; Caer Caradoc rises sharply out of the Stretton Gap [SUPPORTED: https://en.wikipedia.org/wiki/Caer_Caradoc]; Caer Caradoc is the highest point on a narrow whaleback ridge (it tops a narrow whaleback ridge) [SUPPORTED: https://en.wikipedia.org/wiki/Caer_Caradoc]; The summit holds an Iron Age or late Bronze Age hill fort [SUPPORTED, no proving quote: https://en.wikipedia.org/wiki/Caer_Caradoc]; The name Caer Caradog means Caradog''s fort (the fort of Caradog) [SUPPORTED: https://en.wikipedia.org/wiki/Caer_Caradoc]"}]'::jsonb),
    ('1c4b5554-8ffd-45ca-862f-c4c80d9cb627'::uuid, 'card_description', '2400-2000 BC. The most extensively excavated Early Bronze Age site of its period - an agricultural village with a long stratigraphic sequence revealing how Philia culture developed over centuries.', 'Occupied from about 2400 BCE, Marki Alonia in central Cyprus was a farming village of mud-brick houses on stone foundations, its seeds telling of grapes, olives, figs, wheat and barley.', 'teaser-card-s012:1c4b5554-8ffd-45ca-862f-c4c80d9cb627:card_description', 'teaser-card-s012 (teaser-card): teaser card, 185 characters, checked PASS, web-verified VERIFIED', '53b3c428b84e2e3ddee36f787f09709282aed0e4968bffd639a82cef97cddb9f|ac6d2049cc0714584ce956f8b548bb21b06640a28f27d63f77bb473caa56c623|ac6d2049cc0714584ce956f8b548bb21b06640a28f27d63f77bb473caa56c623', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-003", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Occupied from about 2400 BCE, Marki Alonia in central Cyprus was a farming village of mud-brick houses on stone foundations, its seeds telling of grapes, olives, figs, wheat and barley."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-003 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the site was occupied from about 2400 BCE [S3]; Marki Alonia is in central Cyprus [S1]; it was an agricultural (farming) village [S6]; its buildings were made of mud-bricks [S5]; the buildings stood on stone foundations [S5]; surviving seeds indicate grapes, olives, figs, wheat and barley [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-008 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Marki Alonia is a prehistoric settlement (village) in central Cyprus [SUPPORTED: https://en.wikipedia.org/wiki/Marki_Alonia]; Marki Alonia was occupied from about 2400 BCE [SUPPORTED: https://en.wikipedia.org/wiki/Marki_Alonia]; Marki Alonia was a farming (agricultural) village [SUPPORTED: https://en.wikipedia.org/wiki/Marki_Alonia]; The houses were built of mud-brick [SUPPORTED: https://en.wikipedia.org/wiki/Marki_Alonia]; The mud-brick houses were set on stone foundations [SUPPORTED: https://en.wikipedia.org/wiki/Marki_Alonia]; Its surviving seeds indicate grapes, olives and figs [SUPPORTED: https://en.wikipedia.org/wiki/Marki_Alonia]; Its surviving seeds indicate wheat and barley as staple cereals [SUPPORTED: https://en.wikipedia.org/wiki/Marki_Alonia]"}]'::jsonb),
    ('1e2fb44b-2c93-4ad8-827c-e9f1b61136ff'::uuid, 'card_description', 'A fortified city founded as Teotihuacan declined. The Matlatzincas later conquered and expanded it, adding plazas and pyramid complexes.', 'On the hill Tetépetl, 2,700 meters up, the fortified city of Teotenango lasted about 1,000 years. All around it, protruding rocks bear petroglyphs of signs and symbols.', 'teaser-card-s012:1e2fb44b-2c93-4ad8-827c-e9f1b61136ff:card_description', 'teaser-card-s012 (teaser-card): teaser card, 168 characters, checked PASS, web-verified VERIFIED', '3b5d6a28be0f3c2853f2ff0f23f06504f209757edef0c1dd897fb2dd7d2d09be|78a7533e01003a6ea1b16f482446a420800477b12ae5a3952485b09335a6a744|78a7533e01003a6ea1b16f482446a420800477b12ae5a3952485b09335a6a744', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-003", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "On the hill Tetépetl, 2,700 meters up, the fortified city of Teotenango lasted about 1,000 years. All around it, protruding rocks bear petroglyphs of signs and symbols."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-003 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the site is on the hill Tetépetl [S5]; it lies at 2,700 meters above sea level [S5]; Teotenango was a fortified city [S1]; the city existed for about 1,000 years [S3]; all around the site protruding rocks bear petroglyphs of signs and symbols [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-008 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Teotenango was a pre-Hispanic fortified city in the Valley of Toluca, Mexico (the central claim) [SUPPORTED: https://en.wikipedia.org/wiki/Teotenango]; The city stands on the hill Tetepetl [SUPPORTED: https://en.wikipedia.org/wiki/Teotenango]; The hill (site) lies 2,700 metres above sea level [SUPPORTED: https://en.wikipedia.org/wiki/Teotenango]; The city lasted about 1,000 years [SUPPORTED: https://en.wikipedia.org/wiki/Teotenango]; Naturally protruding rocks all around the site bear petroglyphs [SUPPORTED: https://en.wikipedia.org/wiki/Teotenango]; The petroglyphs are of signs and symbols [SUPPORTED: https://en.wikipedia.org/wiki/Teotenango]"}]'::jsonb),
    ('1e5f61dd-b362-4985-b235-dadeea0eca0f'::uuid, 'card_description', 'Agropastoral settlement at Dhar Tichitt occupied from 2000 BC, with dwellings placed on Saharan cliff edges. Among the earliest farming communities identified in West Africa.', 'Around 2000 BC agropastoral communities settled the cliffs of Tichit and raised stone buildings, the oldest surviving archaeological settlements in West Africa.', 'teaser-card-s012:1e5f61dd-b362-4985-b235-dadeea0eca0f:card_description', 'teaser-card-s012 (teaser-card): teaser card, 160 characters, checked PASS, web-verified VERIFIED', 'eeb326820b8cdd80ac8994c697eb9549b293eeba584e598562fac6c9dbcd9e75|c70aedbaeacac53e47e6652933adb299c814a92fa9a3c45dfeec05fa3cf24d03|c70aedbaeacac53e47e6652933adb299c814a92fa9a3c45dfeec05fa3cf24d03', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-003", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Around 2000 BC agropastoral communities settled the cliffs of Tichit and raised stone buildings, the oldest surviving archaeological settlements in West Africa."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-003 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the site was settled around 2000 BC [S1]; the settlers were agropastoral communities [S1]; the settlements were on the cliffs [S3]; the settlements included stone buildings [S3]; they are the oldest surviving archaeological settlements in West Africa [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-009 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Tichit is an archaeological settlement site (the Neolithic settlements of Dhar Tichitt beside the village of Tichit) [SUPPORTED: https://en.wikipedia.org/wiki/Tichit]; The place is in Mauritania [SUPPORTED: https://en.wikipedia.org/wiki/Tichit]; Around 2000 BC agropastoral communities settled there [SUPPORTED: https://en.wikipedia.org/wiki/Tichit]; The settlements were on the cliffs and included stone buildings [SUPPORTED: https://en.wikipedia.org/wiki/Tichit]; They are the oldest surviving archaeological settlements in West Africa [SUPPORTED: https://en.wikipedia.org/wiki/Tichit]"}]'::jsonb),
    ('1e9f1c86-dabd-4cf8-90f8-87c64a8ccc5c'::uuid, 'card_description', 'Neolithic herding cave 630 metres above sea level on Naxos, occupied from Late Neolithic to Early Cycladic III. No crop residue found — archaeologists believe it served as a seasonal animal shelter.', 'On Mount Zas on Naxos, 630m above sea level, the Cave of Zeus holds large stalactites and stalagmites. In one telling, the young Zeus hid here from his father, Cronus.', 'teaser-card-s012:1e9f1c86-dabd-4cf8-90f8-87c64a8ccc5c:card_description', 'teaser-card-s012 (teaser-card): teaser card, 167 characters, checked PASS, web-verified VERIFIED', '4bbf1bfce8f6839d16531ce8b2e93cf8c4742260a6751f8cd627cbbb0da1aaf1|eb91391ded17b6aa5b17c3937bcf2b880cccdc963a34fd9abf66dda7d74eb6b4|eb91391ded17b6aa5b17c3937bcf2b880cccdc963a34fd9abf66dda7d74eb6b4', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-003", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "On Mount Zas on Naxos, 630m above sea level, the Cave of Zeus holds large stalactites and stalagmites. In one telling, the young Zeus hid here from his father, Cronus."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-003 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the cave is on Mount Zas [S1]; it is on Naxos [S1]; it lies 630 m above sea level [S5]; large stalactites and stalagmites are inside the cave [S6]; in one telling, the young Zeus hid in the cave from his father Cronus [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-009 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "The Cave of Zeus is a cave (an ancient Greek cave, occupied from the Late Neolithic to Early Cycladic III) [SUPPORTED: https://en.wikipedia.org/wiki/Cave_of_Zas_(Naxos)]; The cave is on Mount Zas on the island of Naxos (Greece) [SUPPORTED: https://en.wikipedia.org/wiki/Mount_Zas]; The cave lies 630 m above sea level [SUPPORTED: https://en.wikipedia.org/wiki/Cave_of_Zas_(Naxos)]; The cave holds large stalactites and stalagmites [SUPPORTED: https://en.wikipedia.org/wiki/Cave_of_Zas_(Naxos)]; In one telling (Agathosthenes''), Zeus spent his childhood in this cave [SUPPORTED: https://en.wikipedia.org/wiki/Cave_of_Zas_(Naxos)]; In that telling the young Zeus was hiding here from his father, Cronus [SUPPORTED: https://en.wikipedia.org/wiki/Cave_of_Zas_(Naxos)]"}]'::jsonb),
    ('1ee1e668-a44a-47f0-840a-c1d5e804ff2c'::uuid, 'card_description', 'A 15th-century Inca fort of large walls, terraces, and staircases guarding the approaches to Cusco. Its position on the outer perimeter made it a sentinel for the Inca capital.', 'Above the Cusco valley and Tambo Machay lie the military ruins of the Puka Pukara Archaeological Complex, the red fortress, probably built, a theory holds, under Pachacutec.', 'teaser-card-s012:1ee1e668-a44a-47f0-840a-c1d5e804ff2c:card_description', 'teaser-card-s012 (teaser-card): teaser card, 173 characters, checked PASS, web-verified VERIFIED', 'a644776b9873f8b944482fd07a0314add74badaf0ac7415006c918b99de9f64a|065dbfcf78a42324807e374a50261911f157c5de4913c8232ceb75281aed773d|065dbfcf78a42324807e374a50261911f157c5de4913c8232ceb75281aed773d', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-003", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Above the Cusco valley and Tambo Machay lie the military ruins of the Puka Pukara Archaeological Complex, the red fortress, probably built, a theory holds, under Pachacutec."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-003 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the site lies on high ground above the Cusco valley and Tambo Machay [S3]; the site consists of military ruins [S1]; its name means red fortress [S1]; a theory holds it was probably built during the reign of Pachacutec [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-009 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Puka Pukara is a site of military ruins (a fort) [SUPPORTED: https://en.wikipedia.org/wiki/Puka_Pukara]; It is in Peru, near Cusco [SUPPORTED: https://en.wikipedia.org/wiki/Puka_Pukara]; It lies above the Cusco valley [SUPPORTED: https://en.wikipedia.org/wiki/Puka_Pukara]; It lies above Tambo Machay [SUPPORTED: https://en.wikipedia.org/wiki/Puka_Pukara]; The name means the red fortress [SUPPORTED: https://en.wikipedia.org/wiki/Puka_Pukara]; It was probably built under Pachacutec, according to a theory [SUPPORTED: https://en.wikipedia.org/wiki/Puka_Pukara]"}]'::jsonb),
    ('1fe816f4-f921-45ff-97b7-0ca7d1d0d009'::uuid, 'card_description', 'The remains of an Eastern Roman castle from the 4th century AD. Both above-ground fortifications and underground chambers survive at the site.', 'Beneath Zerzevan Castle, a 4th century Eastern Roman military base on a rocky hill, excavations revealed underground structures, among them a temple of Mithraism, a mystery religion.', 'teaser-card-s012:1fe816f4-f921-45ff-97b7-0ca7d1d0d009:card_description', 'teaser-card-s012 (teaser-card): teaser card, 182 characters, checked PASS, web-verified VERIFIED', '1a2e4825584aba235ead7e7826740191f90ed041ca85d833a5646bb50ca22d4b|fec809b3107be034a98d205b5bd8342be016ceaf663e762d10d691fb1ec81aed|fec809b3107be034a98d205b5bd8342be016ceaf663e762d10d691fb1ec81aed', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-003", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Beneath Zerzevan Castle, a 4th century Eastern Roman military base on a rocky hill, excavations revealed underground structures, among them a temple of Mithraism, a mystery religion."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-003 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Zerzevan Castle was built in the 4th century [S3]; it was an Eastern Roman military base [S1, S3]; it stands on a rocky hill [S5]; excavations at the site revealed underground structures [S2]; among the underground structures is a temple of Mithraism [S2]; Mithraism was a mystery religion [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-009 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Zerzevan Castle is a castle, a military base (ruined Eastern Roman castle), in Turkey [SUPPORTED: https://en.wikipedia.org/wiki/Zerzevan_Castle]; It is a 4th century Eastern Roman military base [SUPPORTED: https://en.wikipedia.org/wiki/Zerzevan_Castle]; It stands on a rocky hill [SUPPORTED: https://en.wikipedia.org/wiki/Zerzevan_Castle]; The castle has underground structures [SUPPORTED: https://en.wikipedia.org/wiki/Zerzevan_Castle]; Archaeological excavations at the site revealed the underground structures, among them a temple of Mithraism [SUPPORTED: https://en.wikipedia.org/wiki/Zerzevan_Castle]; Among the underground structures unearthed is a Mithraic temple (temple of Mithraism) [SUPPORTED: https://en.wikipedia.org/wiki/Zerzevan_Castle]; Mithraism is a mystery religion [SUPPORTED: https://en.wikipedia.org/wiki/Mithraism]"}]'::jsonb),
    ('1feef50a-659c-4a9b-bebe-d12b641036b1'::uuid, 'card_description', 'One of six Iron Age oppida in the Vaunage valley, first occupied around 700 BC. Its inhabitants moved between nearby hilltop settlements as fortunes shifted.', 'On a hilltop above the Vaunage stands the Oppidum de Roque de Viou, one of six Iron Age oppida there. The Volques first occupied it about 700 BCE, and left around 600.', 'teaser-card-s012:1feef50a-659c-4a9b-bebe-d12b641036b1:card_description', 'teaser-card-s012 (teaser-card): teaser card, 167 characters, checked PASS, web-verified VERIFIED', 'e5ddf63d3eb823083fe98a3e8e67bea22b0214ab957327467989dedbdcd8de1d|2a64b41713e9e5929c08349652a758f2c26abfdfe29e67e1810c8c240747f0dd|2a64b41713e9e5929c08349652a758f2c26abfdfe29e67e1810c8c240747f0dd', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-003", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "On a hilltop above the Vaunage stands the Oppidum de Roque de Viou, one of six Iron Age oppida there. The Volques first occupied it about 700 BCE, and left around 600."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-003 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the oppidum is on a hilltop [S1]; it overlooks the Vaunage [S1]; it is one of six Iron Age oppida in the Vaunage [S2]; the Volques first occupied it about 700 BCE [S4]; the Volques left around 600 [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-009 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "The Oppidum de Roque de Viou is an Iron Age oppidum (a fortified hilltop settlement) in France [SUPPORTED: https://en.wikipedia.org/wiki/Oppidum_de_Roque_de_Viou]; It stands on a hilltop above the Vaunage [SUPPORTED: https://en.wikipedia.org/wiki/Oppidum_de_Roque_de_Viou]; It is one of six Iron Age oppida in the Vaunage [SUPPORTED: https://en.wikipedia.org/wiki/Oppidum_de_Roque_de_Viou]; The Volques first occupied it about 700 BCE [SUPPORTED: https://en.wikipedia.org/wiki/Oppidum_de_Roque_de_Viou]; The Volques left it around 600 BCE [SUPPORTED: https://en.wikipedia.org/wiki/Oppidum_de_Roque_de_Viou]"}]'::jsonb),
    ('20f27e8d-091e-41c2-9640-936e5833178c'::uuid, 'card_description', 'The Hassle treasure was found at Hassle in the parish of Glanshammar during 1936.', 'The Hassle treasure, found in 1936: a large bronze cauldron of a cultic kind usually found in Italy and Greece, cradling two Hallstatt-type swords. Every item was imported.', 'teaser-card-s012:20f27e8d-091e-41c2-9640-936e5833178c:card_description', 'teaser-card-s012 (teaser-card): teaser card, 172 characters, checked PASS, web-verified VERIFIED', '8056f0e148d7c0364ca2d8bfc2ebc89bb0591e682afdfaf80ebdd27753a41362|9232497e9466296a9c5247871d6940572f67b7e36e49a4208eca796b6b55c1d5|9232497e9466296a9c5247871d6940572f67b7e36e49a4208eca796b6b55c1d5', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-004", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "The Hassle treasure, found in 1936: a large bronze cauldron of a cultic kind usually found in Italy and Greece, cradling two Hallstatt-type swords. Every item was imported."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-004 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the find is called the Hassle treasure [S1]; it was found in 1936 [S1]; it includes a large bronze cauldron [S2]; the cauldron is of a cultic kind usually found in Italy and Greece [S4]; the cauldron contained two swords [S2]; the swords are of the Hallstatt type [S2]; every item of the treasure was imported [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-010 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Hassle, Sweden, is the findspot of a treasure (hoard), the Hassle treasure - the site is a hoard find location, not a fort, tomb or settlement [SUPPORTED: https://en.wikipedia.org/wiki/Hassle]; The site is located in Sweden (Örebro Municipality, Örebro County) [SUPPORTED: https://en.wikipedia.org/wiki/Hassle]; The Hassle treasure was found in 1936 [SUPPORTED: https://en.wikipedia.org/wiki/Hassle]; The hoard includes a large bronze cauldron [SUPPORTED: https://en.wikipedia.org/wiki/Hassle]; The cauldron is of a cultic kind usually found in Italy and Greece [SUPPORTED: https://en.wikipedia.org/wiki/Hassle]; The cauldron held (cradled) two Hallstatt-type swords [SUPPORTED: https://en.wikipedia.org/wiki/Hassle]; Every item of the treasure was imported [SUPPORTED: https://en.wikipedia.org/wiki/Hassle]"}]'::jsonb),
    ('218a4df9-1bc1-43ce-a054-1d964d7232a4'::uuid, 'card_description', 'The Tarragal Caves are a network of large limestone caves and rockshelters which overlook the Bridgewater Lakes near the towns of Tarragal and Cape Bridgewater.', 'Above the Bridgewater Lakes, the Tarragal Caves were identified as important Aboriginal camping places. Excavation revealed shell middens and earth ovens over 11,000 years old.', 'teaser-card-s012:218a4df9-1bc1-43ce-a054-1d964d7232a4:card_description', 'teaser-card-s012 (teaser-card): teaser card, 176 characters, checked PASS, web-verified VERIFIED', '7ecdd16abafa3e676b08998d33094ac9c249a61ce08a8325f27a75aec6c8f8b8|e52850fba9d809cde2a492f0d9f35e8e77a86b873bee74b5fef1a2708b1dc5b2|e52850fba9d809cde2a492f0d9f35e8e77a86b873bee74b5fef1a2708b1dc5b2', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-rewrite1-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Above the Bridgewater Lakes, the Tarragal Caves were identified as important Aboriginal camping places. Excavation revealed shell middens and earth ovens over 11,000 years old."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check1-001 (check1), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the Tarragal Caves are above (overlook) the Bridgewater Lakes [S1]; the caves were identified as important Aboriginal camping places [S2]; excavation revealed shell middens [S2]; excavation revealed earth ovens [S2]; the shell middens and earth ovens are over 11,000 years old [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-010 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "The Tarragal Caves are a cave site (a network of limestone caves and rockshelters) above/overlooking the Bridgewater Lakes [SUPPORTED: https://en.wikipedia.org/wiki/Tarragal_Caves]; The caves are near Tarragal and Cape Bridgewater, Victoria (Australia) [SUPPORTED: https://en.wikipedia.org/wiki/Tarragal_Caves]; The caves were identified as important Aboriginal camping places [SUPPORTED: https://en.wikipedia.org/wiki/Tarragal_Caves]; Excavation revealed shell middens over 11,000 years old [SUPPORTED: https://en.wikipedia.org/wiki/Tarragal_Caves]; Excavation revealed earth ovens over 11,000 years old [SUPPORTED: https://en.wikipedia.org/wiki/Tarragal_Caves]; The caves were excavated (by Harry Lourandos, late 1970s) [SUPPORTED: https://en.wikipedia.org/wiki/Tarragal_Caves]"}]'::jsonb),
    ('23242c3f-c221-4689-a166-af4f464f5c1b'::uuid, 'card_description', 'An Italic necropolis from the 1st millennium BC. Burial practices of pre-Roman peoples here offer a rare window into how Italic tribes honored their dead.', 'Found by accident in 1992 while a warehouse was being built, the Necropolis of Fossa holds approximately 500 tombs: tumuli, pits, chamber tombs and infants laid in ceramic tiles.', 'teaser-card-s012:23242c3f-c221-4689-a166-af4f464f5c1b:card_description', 'teaser-card-s012 (teaser-card): teaser card, 178 characters, checked PASS, web-verified VERIFIED', 'a025c4ab53bdc75401d0c1c0e18d3a2e6705327787ab9b7c49db59a536f789aa|e22d0447132f35dba3de4ebf340626eaff069f8ce7da02bc165f08cfb23d472a|e22d0447132f35dba3de4ebf340626eaff069f8ce7da02bc165f08cfb23d472a', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-004", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Found by accident in 1992 while a warehouse was being built, the Necropolis of Fossa holds approximately 500 tombs: tumuli, pits, chamber tombs and infants laid in ceramic tiles."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-004 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the site was found by accident [S5]; it was found in 1992 [S5]; it was found while a warehouse was being built [S5]; the Necropolis of Fossa is a necropolis [S1]; it holds approximately 500 tombs [S6]; the tombs include tumuli [S6]; the tombs include pits [S6]; the tombs include chamber tombs [S6]; the tombs include infant burials in ceramic tiles [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-010 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "The Necropolis of Fossa is a necropolis (Italic burial ground) in Fossa, L''Aquila province, Abruzzo, Italy [SUPPORTED: https://en.wikipedia.org/wiki/Necropolis_of_Fossa]; The necropolis was found by accident [SUPPORTED: https://en.wikipedia.org/wiki/Necropolis_of_Fossa]; The necropolis was found in 1992 [SUPPORTED: https://en.wikipedia.org/wiki/Necropolis_of_Fossa]; It was found while a warehouse was being built [SUPPORTED: https://en.wikipedia.org/wiki/Necropolis_of_Fossa]; The necropolis holds approximately 500 tombs [SUPPORTED: https://en.wikipedia.org/wiki/Necropolis_of_Fossa]; The tombs include tumuli [SUPPORTED: https://en.wikipedia.org/wiki/Necropolis_of_Fossa]; The tombs include pit graves (pits) [SUPPORTED: https://en.wikipedia.org/wiki/Necropolis_of_Fossa]; The tombs include chamber tombs [SUPPORTED: https://en.wikipedia.org/wiki/Necropolis_of_Fossa]; The necropolis includes infants laid in ceramic tiles [SUPPORTED: https://en.wikipedia.org/wiki/Necropolis_of_Fossa]; The four tomb types (tumuli, pits, chamber tombs, infant burials in ceramic tiles) are the types of the roughly 500 tombs [SUPPORTED: https://en.wikipedia.org/wiki/Necropolis_of_Fossa]"}]'::jsonb),
    ('235def6a-3971-4308-9248-172c2cb39025'::uuid, 'card_description', 'When the antiquarian A. D. Passmore investigated the site during the 1890s he found nine stones, mostly buried.', 'Five partly buried stones are all that remain of Day House Lane Stone Circle near Swindon, a ring of sarsens that probably spanned about 69 metres and possibly held over thirty stones.', 'teaser-card-s012:235def6a-3971-4308-9248-172c2cb39025:card_description', 'teaser-card-s012 (teaser-card): teaser card, 184 characters, checked PASS, web-verified VERIFIED', '0df9492448152c64cbfcca2b10e132f8fef5b5de644c8da10e3433db9886a1da|434834f70ebe21e2d877217c5b4a2b3c57f41b33dfdcff3990e123604ce6fead|434834f70ebe21e2d877217c5b4a2b3c57f41b33dfdcff3990e123604ce6fead', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-004", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Five partly buried stones are all that remain of Day House Lane Stone Circle near Swindon, a ring of sarsens that probably spanned about 69 metres and possibly held over thirty stones."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-004 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "five partly buried stones are what remains of the site [S2]; Day House Lane Stone Circle is a stone circle [S1]; it lies near Swindon [S1]; it was a ring of sarsen stones [S3]; it probably spanned about 69 metres [S3]; it possibly held over thirty stones [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-010 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Day House Lane Stone Circle is a stone circle (a prehistoric ring of standing stones) near Swindon, Wiltshire, England [SUPPORTED: https://en.wikipedia.org/wiki/Day_House_Lane_Stone_Circle]; The circle lies near Swindon [SUPPORTED: https://en.wikipedia.org/wiki/Day_House_Lane_Stone_Circle]; Five stones remain of the circle [SUPPORTED: https://en.wikipedia.org/wiki/Day_House_Lane_Stone_Circle]; The remaining stones are partly buried [SUPPORTED: https://en.wikipedia.org/wiki/Day_House_Lane_Stone_Circle]; The five stones are all that remain of the circle (nine were recorded in the 1890s, only five by the early 21st century) [SUPPORTED: https://en.wikipedia.org/wiki/Day_House_Lane_Stone_Circle]; The circle was a ring of sarsens [SUPPORTED: https://en.wikipedia.org/wiki/Day_House_Lane_Stone_Circle]; The circle probably spanned about 69 metres [SUPPORTED: https://en.wikipedia.org/wiki/Day_House_Lane_Stone_Circle]; The circle possibly held over thirty stones [SUPPORTED: https://en.wikipedia.org/wiki/Day_House_Lane_Stone_Circle]"}]'::jsonb),
    ('23cb48d4-7ca0-4105-a97e-f60f67537bc9'::uuid, 'card_description', 'The earthworks cover an area of about 10 acres, of which about 4.5 acres are inside the ramparts.', 'Abbotsbury Castle, an Iron Age hillfort above the village of Abbotsbury, overlooks the English Channel. Held by the Durotriges, it fell with little struggle to Vespasian''s legion in AD 43.', 'teaser-card-s012:23cb48d4-7ca0-4105-a97e-f60f67537bc9:card_description', 'teaser-card-s012 (teaser-card): teaser card, 188 characters, checked PASS, web-verified VERIFIED', '6318342c311e6699d20e75c156c5a513cafc04a4ba19969c46b143ece6460e25|091c5bb5a9debf59bfbc4ad99659089d303281a94baaee908a11c335e4e6b3dd|091c5bb5a9debf59bfbc4ad99659089d303281a94baaee908a11c335e4e6b3dd', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-rewrite-v-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Abbotsbury Castle, an Iron Age hillfort above the village of Abbotsbury, overlooks the English Channel. Held by the Durotriges, it fell with little struggle to Vespasian''s legion in AD 43."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-v-001 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Abbotsbury Castle is an Iron Age hillfort [S1]; it lies above the village of Abbotsbury [S1]; it overlooks the English Channel [S2]; the fort was held (occupied) by the Durotriges [S4]; it fell with little struggle [S4]; it fell to Vespasian''s legion [S4]; the fall came in AD 43, with the Roman invasion [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify2-002 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Abbotsbury Castle is a hillfort (a fort on a hill) [SUPPORTED: https://dorset-nl.org.uk/location/abbotsbury-hillfort/]; The hillfort dates to the Iron Age [SUPPORTED: https://dorset-nl.org.uk/location/abbotsbury-hillfort/]; The hillfort lies above the village of Abbotsbury (in Dorset, England) [SUPPORTED: https://dorset-nl.org.uk/location/abbotsbury-hillfort/]; The hillfort overlooks the English Channel [SUPPORTED: https://dorset-nl.org.uk/location/abbotsbury-hillfort/]; The fort was held (occupied) by the Durotriges [SUPPORTED: https://dorset-nl.org.uk/location/abbotsbury-hillfort/]; The fort fell with little struggle [SUPPORTED: https://dorset-nl.org.uk/location/abbotsbury-hillfort/]; The fort fell to Vespasian''s legion [SUPPORTED: https://dorset-nl.org.uk/location/abbotsbury-hillfort/]; The fall of the fort happened in AD 43, when the Romans invaded [SUPPORTED: https://dorset-nl.org.uk/location/abbotsbury-hillfort/]"}]'::jsonb),
    ('23cd75bc-22da-4f28-aa83-f527fdf84e2e'::uuid, 'card_description', 'Eight Thule-period Inuit mummies found in 1972 — naturally preserved by cold dry air. Six adults and two children, offering insights into Arctic diet, disease, and daily life 500 years ago.', 'Two hunters chasing rock ptarmigans on October 9, 1972 found a grave at Qilakitsoq holding several mummies: Inuit of the Thule period, who probably died around 1475.', 'teaser-card-s012:23cd75bc-22da-4f28-aa83-f527fdf84e2e:card_description', 'teaser-card-s012 (teaser-card): teaser card, 165 characters, checked PASS, web-verified VERIFIED', '3fc15fa19f0765a309f0b281930e61597ebda5cfae342db99cc2db4728cea5d0|9495b08c7b94fa43552a9423ba815967766034da7c1daa646c430bd674ed2f2b|9495b08c7b94fa43552a9423ba815967766034da7c1daa646c430bd674ed2f2b', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-rewrite-v-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Two hunters chasing rock ptarmigans on October 9, 1972 found a grave at Qilakitsoq holding several mummies: Inuit of the Thule period, who probably died around 1475."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-v-001 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "two hunters made the find [S6]; the hunters were out hunting (chasing) rock ptarmigans [S6]; the find was made on October 9, 1972 [S6]; they found a grave at Qilakitsoq [S2, S6]; the grave held several mummies [S6]; the mummies were Inuit [S3]; the mummies were of the Thule period [S2]; they probably died around 1475 [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify2-002 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Qilakitsoq is an archaeological site (with a grave holding mummies) in Greenland [SUPPORTED: https://en.wikipedia.org/wiki/Qilakitsoq]; A grave holding several mummies was found at Qilakitsoq [SUPPORTED: https://en.wikipedia.org/wiki/Qilakitsoq]; The grave was found by two hunters [SUPPORTED: https://en.wikipedia.org/wiki/Qilakitsoq]; The grave was found on October 9, 1972 [SUPPORTED: https://en.wikipedia.org/wiki/Qilakitsoq]; The hunters were chasing (hunting) rock ptarmigans when they found it [SUPPORTED: https://en.wikipedia.org/wiki/Qilakitsoq]; The mummies are Inuit [SUPPORTED: https://en.wikipedia.org/wiki/Qilakitsoq]; The mummies are of the Thule period [SUPPORTED: https://en.wikipedia.org/wiki/Qilakitsoq]; The mummies probably died around 1475 [SUPPORTED: https://en.wikipedia.org/wiki/Qilakitsoq]"}]'::jsonb),
    ('23ddb957-c31f-4ec9-9fcc-e02bc5316c5c'::uuid, 'card_description', 'By the 4th century the villa was now a large courtyard villa enclosed on at least three sides.', 'A farmer digging out a ferret found Rockbourne Roman Villa in 1942. Two Roman milestones were reused in its fabric, and in 1967 a pottery jar yielded a hoard of 7717 bronze coins.', 'teaser-card-s012:23ddb957-c31f-4ec9-9fcc-e02bc5316c5c:card_description', 'teaser-card-s012 (teaser-card): teaser card, 179 characters, checked PASS, web-verified VERIFIED', '3794b39967cc5f275716f5160f15792bfb04ff431f2dcbb97a8b20b4a7332a63|3f4db0d5cf1ad70a7726706fcc3f3edfde254996c1136daa5c70c9e5a9662645|3f4db0d5cf1ad70a7726706fcc3f3edfde254996c1136daa5c70c9e5a9662645', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-004", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "A farmer digging out a ferret found Rockbourne Roman Villa in 1942. Two Roman milestones were reused in its fabric, and in 1967 a pottery jar yielded a hoard of 7717 bronze coins."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-004 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Rockbourne Roman Villa was found by a farmer [S2]; the farmer was digging out a ferret [S2]; it was found in 1942 [S2]; it is a Roman villa [S1]; two Roman milestones were reused in its fabric [S8]; in 1967 a hoard was found in a pottery jar [S5]; the hoard held 7717 bronze coins [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-011 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Rockbourne Roman Villa is a Roman villa (courtyard villa) at Rockbourne in Hampshire, England (central claim) [SUPPORTED: https://en.wikipedia.org/wiki/Rockbourne_Roman_Villa]; The villa was found in 1942 [SUPPORTED: https://en.wikipedia.org/wiki/Rockbourne_Roman_Villa]; It was found by a farmer digging out a ferret [SUPPORTED: https://en.wikipedia.org/wiki/Rockbourne_Roman_Villa]; Two Roman milestones were reused in the fabric of the villa [SUPPORTED: https://en.wikipedia.org/wiki/Rockbourne_Roman_Villa]; In 1967 a hoard was found at the villa [SUPPORTED: https://en.wikipedia.org/wiki/Rockbourne_Roman_Villa]; The hoard was in a pottery jar [SUPPORTED: https://en.wikipedia.org/wiki/Rockbourne_Roman_Villa]; The hoard consisted of 7717 bronze coins [SUPPORTED: https://en.wikipedia.org/wiki/Rockbourne_Roman_Villa]"}]'::jsonb),
    ('25ba654d-b16a-44bc-9022-459aeb272ca2'::uuid, 'card_description', 'A settlement on the pilgrimage route from Kufa to Mecca. Excavations yielded key evidence about early Islamic material culture, including ceramics and architecture.', 'Al-Rabadha, on the pilgrim route from Kufa to Mecca, is dominated by a palace of 13 rooms opening on a central courtyard, with evidence of ovens, grain storage and a glass-making furnace.', 'teaser-card-s012:25ba654d-b16a-44bc-9022-459aeb272ca2:card_description', 'teaser-card-s012 (teaser-card): teaser card, 187 characters, checked PASS, web-verified VERIFIED', '1935f9ff778df6851452a8c46d82174921665be256c5e402a63fbcf7709adc34|052c43b9a1103d7dcc8fec7f094f68a833ce5f785284adc4a33d92fa20b2bc27|052c43b9a1103d7dcc8fec7f094f68a833ce5f785284adc4a33d92fa20b2bc27', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-rewrite1-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Al-Rabadha, on the pilgrim route from Kufa to Mecca, is dominated by a palace of 13 rooms opening on a central courtyard, with evidence of ovens, grain storage and a glass-making furnace."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check1-001 (check1), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Al-Rabadha lies on the pilgrim route from Kufa to Mecca [S1]; the site is dominated by a palace [S5]; the palace has 13 rooms [S5]; the rooms open on a central courtyard [S5]; there is evidence of ovens [S6]; there is evidence of grain storage [S6]; there is evidence of a glass-making furnace [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-011 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Al-Rabadha is a settlement (town) in Saudi Arabia (central claim: an Early Islamic settlement site) [SUPPORTED: https://en.wikipedia.org/wiki/Al-Rabadha]; It lies on the pilgrim route from Kufa to Mecca [SUPPORTED: https://en.wikipedia.org/wiki/Al-Rabadha]; The site is dominated by a palace [SUPPORTED: https://en.wikipedia.org/wiki/Al-Rabadha]; The palace has 13 rooms [SUPPORTED: https://en.wikipedia.org/wiki/Al-Rabadha]; The rooms open on a central courtyard [SUPPORTED: https://en.wikipedia.org/wiki/Al-Rabadha]; There is evidence of ovens [SUPPORTED: https://en.wikipedia.org/wiki/Al-Rabadha]; There is evidence of grain storage [SUPPORTED: https://en.wikipedia.org/wiki/Al-Rabadha]; There is evidence of a glass-making furnace [SUPPORTED: https://en.wikipedia.org/wiki/Al-Rabadha]"}]'::jsonb),
    ('2607b059-3e7c-4eb3-97b2-737e1517c526'::uuid, 'card_description', 'Capital of the late Scythians from the 3rd century BC, an Iranic people who controlled Crimea. Their culture blended steppe nomadism with Greek urban life.', 'On the edge of Simferopol lie the ruins of Scythian Neapolis, centre of Crimea''s Scythian tribes, once ringed by a large stone wall against the Sarmatians and destroyed by the Goths.', 'teaser-card-s012:2607b059-3e7c-4eb3-97b2-737e1517c526:card_description', 'teaser-card-s012 (teaser-card): teaser card, 182 characters, checked PASS, web-verified VERIFIED', 'd1d37d97e7fa048e6558b55333aeb20ec8aebc3ce724b88f0f82926443c7ab3f|b01df588b75f592c1be4841f6de9ce92f196fc2a242fba1d3530c48faf3d78f0|b01df588b75f592c1be4841f6de9ce92f196fc2a242fba1d3530c48faf3d78f0', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-004", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "On the edge of Simferopol lie the ruins of Scythian Neapolis, centre of Crimea''s Scythian tribes, once ringed by a large stone wall against the Sarmatians and destroyed by the Goths."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-004 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the ruins of Scythian Neapolis lie on the edge of Simferopol [S2]; it was the centre of Crimea''s Scythian tribes [S3]; it was once ringed by a large stone wall [S7]; the wall was built against the Sarmatians [S7]; it was destroyed by the Goths [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-011 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Scythian Neapolis is the ruined settlement (fortified town) of the Scythians in Crimea (central claim: a settlement site) [SUPPORTED: https://en.wikipedia.org/wiki/Scythian_Neapolis]; The ruins lie on the edge (outskirts) of Simferopol [SUPPORTED: https://en.wikipedia.org/wiki/Scythian_Neapolis]; It was the centre of Crimea''s Scythian tribes [SUPPORTED: https://en.wikipedia.org/wiki/Scythian_Neapolis]; It was once ringed by a large stone wall [SUPPORTED: https://en.wikipedia.org/wiki/Scythian_Neapolis]; The wall was against the Sarmatians [SUPPORTED: https://en.wikipedia.org/wiki/Scythian_Neapolis]; It was destroyed by the Goths [SUPPORTED: https://en.wikipedia.org/wiki/Scythian_Neapolis]"}]'::jsonb),
    ('27309875-001f-4c13-a005-17cde60e415c'::uuid, 'card_description', 'Doric temple on Selinus''s acropolis built shortly after the mid-6th century BC, dedicated to Apollo as confirmed by inscription. Hundreds of clay seals recovered suggest it doubled as an archive.', 'Hundreds of seals were recovered from Temple C at Selinus, a Doric temple dedicated to Apollo and probably used as an archive. On one metope, Perseus decapitates Medusa as Athena looks on.', 'teaser-card-s012:27309875-001f-4c13-a005-17cde60e415c:card_description', 'teaser-card-s012 (teaser-card): teaser card, 188 characters, checked PASS, web-verified VERIFIED', '4d779159c244f9b5df01a5b50e6a01b97d687e792e5b087a3c0a4525035b9377|7a62844b2a457cda16f5263654b9e4b41b298cc047f7a113c7ffdfb31c506a0d|7a62844b2a457cda16f5263654b9e4b41b298cc047f7a113c7ffdfb31c506a0d', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-004", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Hundreds of seals were recovered from Temple C at Selinus, a Doric temple dedicated to Apollo and probably used as an archive. On one metope, Perseus decapitates Medusa as Athena looks on."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-004 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "hundreds of seals were recovered from Temple C [S4]; Temple C is at Selinus [S1]; it is a Doric temple [S1]; it was dedicated to Apollo [S4]; it was probably used as an archive [S4]; one metope shows Perseus decapitating Medusa [S6]; on that metope Athena looks on [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-011 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Temple C at Selinus (Sicily, Italy) is a Greek temple (central claim: a temple) [SUPPORTED: https://en.wikipedia.org/wiki/Temple_C_(Selinus)]; The temple is Doric [SUPPORTED: https://en.wikipedia.org/wiki/Temple_C_(Selinus)]; Hundreds of seals were recovered from Temple C [SUPPORTED: https://en.wikipedia.org/wiki/Temple_C_(Selinus)]; The temple was dedicated to Apollo [SUPPORTED, no proving quote: https://en.wikipedia.org/wiki/Temple_C_(Selinus)]; The temple was probably used as an archive [SUPPORTED: https://en.wikipedia.org/wiki/Temple_C_(Selinus)]; On one metope Perseus decapitates Medusa [SUPPORTED: https://en.wikipedia.org/wiki/Temple_C_(Selinus)]; Athena looks on in that metope scene [SUPPORTED: https://en.wikipedia.org/wiki/Temple_C_(Selinus)]"}]'::jsonb),
    ('28402a1d-9e31-4818-9790-783de876cecd'::uuid, 'card_description', 'Isog lies on the northern slope of the mountain Susupillo, which is also the name of the archaeological site south of Isog.', 'On the northern slope of the mountain Susupillo, in the Huánuco Region, lies Isog, whose name possibly comes from the Quechua isu, a skin sickness caused by a certain mite.', 'teaser-card-s012:28402a1d-9e31-4818-9790-783de876cecd:card_description', 'teaser-card-s012 (teaser-card): teaser card, 172 characters, checked PASS, web-verified VERIFIED', '6c2e39473dc287793c29996faed81efaa87f7d28a7c12ecc83e4e3facc0150bd|a9e8908735e07a2275c7420619f21d8341b2ad8b3e3d7ecee0907c3f9dbc5a97|a9e8908735e07a2275c7420619f21d8341b2ad8b3e3d7ecee0907c3f9dbc5a97', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-004", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "On the northern slope of the mountain Susupillo, in the Huánuco Region, lies Isog, whose name possibly comes from the Quechua isu, a skin sickness caused by a certain mite."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-004 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Isog lies on the northern slope of the mountain Susupillo [S4]; Isog is in the Huánuco Region [S2]; the name possibly comes from the Quechua isu [S1]; isu is a skin sickness caused by a certain mite [S1]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-012 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Isog is an archaeological site (a place) in Peru [SUPPORTED: https://en.wikipedia.org/wiki/Isog]; Isog is in the Huánuco Region [SUPPORTED: https://en.wikipedia.org/wiki/Isog]; Isog lies on the northern slope of the mountain Susupillo [SUPPORTED: https://en.wikipedia.org/wiki/Isog]; The name Isog possibly comes from the Quechua word isu [SUPPORTED, no proving quote: https://en.wikipedia.org/wiki/Isog]; Quechua isu means a skin sickness caused by a certain mite [SUPPORTED: https://en.wikipedia.org/wiki/Isog]"}]'::jsonb),
    ('287a5d74-480a-4c9e-a1d8-7c9ad96e31ec'::uuid, 'card_description', 'The settlement was in use from the 2nd century BC to 1st century BC, during the La Tène period.', 'Heidengraben, the pagans'' moat: on the Swabian Jura, the outer fortifications of this Celtic oppidum ring over 1,700 hectares, by surface area the largest in all of mainland Europe.', 'teaser-card-s012:287a5d74-480a-4c9e-a1d8-7c9ad96e31ec:card_description', 'teaser-card-s012 (teaser-card): teaser card, 181 characters, checked PASS, web-verified VERIFIED', '6035cf199fff697d2ffdabe80ccf72eee49f560482d789baf723a12bf839b089|ad356c912a5062431ba9991ceff97c9d9f87d4b16e1cd031344ffe8786e526ca|ad356c912a5062431ba9991ceff97c9d9f87d4b16e1cd031344ffe8786e526ca', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-004", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Heidengraben, the pagans'' moat: on the Swabian Jura, the outer fortifications of this Celtic oppidum ring over 1,700 hectares, by surface area the largest in all of mainland Europe."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-004 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Heidengraben means ''the pagans'' moat'' [S1]; it lies on the Swabian Jura [S1]; it is a Celtic oppidum [S1]; its outer fortifications ring over 1,700 hectares [S4]; by surface area it is the largest oppidum in all of mainland Europe [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-012 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Heidengraben is a Celtic site [SUPPORTED: https://en.wikipedia.org/wiki/Heidengraben]; Heidengraben is an oppidum, a fortified settlement [SUPPORTED: https://en.wikipedia.org/wiki/Heidengraben]; Heidengraben is on the Swabian Jura [SUPPORTED: https://en.wikipedia.org/wiki/Heidengraben]; Heidengraben means the pagans'' moat [SUPPORTED: https://en.wikipedia.org/wiki/Heidengraben]; The oppidum has outer fortifications that enclose an area [SUPPORTED: https://en.wikipedia.org/wiki/Heidengraben]; The area enclosed by the outer fortifications is over 1,700 hectares [SUPPORTED: https://en.wikipedia.org/wiki/Heidengraben]; By surface area Heidengraben is the largest oppidum in all of mainland Europe [SUPPORTED: https://en.wikipedia.org/wiki/Heidengraben]"}]'::jsonb),
    ('29074533-09e3-4f7b-9d43-dbffbf8a0a32'::uuid, 'card_description', 'Roughly 130 metres above the Axe Estuary near Axmouth, this hillfort commands clear sightlines over land and sea. The earthworks follow a prominent hillside above the river mouth.', 'Above the Axe Estuary, the rampart of Hawkesdown Hill still stands up to 4 metres high. Remains suggest a Roman attack, its circumstances unrecorded, or perhaps just training.', 'teaser-card-s012:29074533-09e3-4f7b-9d43-dbffbf8a0a32:card_description', 'teaser-card-s012 (teaser-card): teaser card, 175 characters, checked PASS, web-verified VERIFIED', 'fd2a00da1088f17c5b4cc2f4b76f0fa774e8b7c5eb2f81f1f98dd70dbef45b4d|3bccec3c57cf3e8876e05a433307571ccfc4e9662aa9756aeca1c5f273c5f461|3bccec3c57cf3e8876e05a433307571ccfc4e9662aa9756aeca1c5f273c5f461', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-004", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Above the Axe Estuary, the rampart of Hawkesdown Hill still stands up to 4 metres high. Remains suggest a Roman attack, its circumstances unrecorded, or perhaps just training."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-004 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Hawkesdown Hill lies above the Axe Estuary [S2]; it has a rampart [S5]; the rampart still stands up to 4 metres high [S5]; remains suggest a Roman attack [S7]; the circumstances of that attack are unrecorded [S7]; the remains may instead reflect only training [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-012 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Hawkesdown Hill is a hill fort (Iron Age) above the Axe Estuary [SUPPORTED: https://en.wikipedia.org/wiki/Hawkesdown_Hill]; Hawkesdown Hill is an Iron Age hill fort (a fortification with a rampart) [SUPPORTED: https://en.wikipedia.org/wiki/Hawkesdown_Hill]; The rampart still stands up to 4 metres high [SUPPORTED: https://en.wikipedia.org/wiki/Hawkesdown_Hill]; Remains found on the site suggest an attack by the Romans [SUPPORTED: https://en.wikipedia.org/wiki/Hawkesdown_Hill]; The circumstances of the attack are unrecorded [SUPPORTED: https://en.wikipedia.org/wiki/Hawkesdown_Hill]; The remains may instead reflect only training use of an abandoned site [SUPPORTED: https://en.wikipedia.org/wiki/Hawkesdown_Hill]"}]'::jsonb),
    ('29440d54-9b26-4f92-9f0c-b7573373d12c'::uuid, 'card_description', 'The recorded remains belong mainly to the Upper Solutrean and the Lower Magdalenian ages, although older objects are also found.', 'In Cantabria, the walls of the Cave of La Pasiega carry paintings and engravings of horses, deer and cattle, beside many abstract symbols that suggest patterns of repeated characters.', 'teaser-card-s012:29440d54-9b26-4f92-9f0c-b7573373d12c:card_description', 'teaser-card-s012 (teaser-card): teaser card, 183 characters, checked PASS, web-verified VERIFIED', '1a430fad040f37e86089c6da4acdde67d7b92eabad16fdd41f1e51e7bb1d72a7|aa5155bdf96b0c1bc3aff6172ccdbf2f4cc61f9d5f99cb798809a9cdf28bee5e|aa5155bdf96b0c1bc3aff6172ccdbf2f4cc61f9d5f99cb798809a9cdf28bee5e', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-004", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "In Cantabria, the walls of the Cave of La Pasiega carry paintings and engravings of horses, deer and cattle, beside many abstract symbols that suggest patterns of repeated characters."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-004 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the Cave of La Pasiega is in Cantabria [S1]; its walls carry paintings [S3]; its walls carry engravings [S3]; the images show horses [S4]; the images show deer [S4]; the images show cattle [S4]; there are many abstract symbols [S5]; the symbols suggest patterns of repeated characters [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-012 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "La Pasiega is a cave (Cave of La Pasiega) with Paleolithic art [SUPPORTED: https://en.wikipedia.org/wiki/Cave_of_La_Pasiega]; The cave is in Cantabria [SUPPORTED: https://en.wikipedia.org/wiki/Cave_of_La_Pasiega]; The cave walls carry paintings [SUPPORTED: https://en.wikipedia.org/wiki/Cave_of_La_Pasiega]; The cave walls carry engravings [SUPPORTED: https://en.wikipedia.org/wiki/Cave_of_La_Pasiega]; The images include horses [SUPPORTED: https://en.wikipedia.org/wiki/Cave_of_La_Pasiega]; The images include deer [SUPPORTED: https://en.wikipedia.org/wiki/Cave_of_La_Pasiega]; The images include cattle [SUPPORTED: https://en.wikipedia.org/wiki/Cave_of_La_Pasiega]; The cave has many abstract symbols beside the animal images [SUPPORTED: https://en.wikipedia.org/wiki/Cave_of_La_Pasiega]; The abstract symbols suggest patterns of repeated characters [SUPPORTED: https://en.wikipedia.org/wiki/Cave_of_La_Pasiega]"}]'::jsonb),
    ('29556c62-1823-4aa0-9873-12121d2cf630'::uuid, 'card_description', 'One of the greatest Mesoamerican sites, occupied from 1500 BC to 1200 AD. Most of it now lies buried beneath a modern capital city.', 'Kaminal Juyu Parque Arqueológico, a Maya site in Guatemala City, had some 200 platforms and pyramidal mounds when first mapped scientifically; huge thrones and stelae attest to its might.', 'teaser-card-s012:29556c62-1823-4aa0-9873-12121d2cf630:card_description', 'teaser-card-s012 (teaser-card): teaser card, 187 characters, checked PASS, web-verified VERIFIED', 'e028255db6534a6828ad7ce30173b96f110dc7812c8a31da5c38e90fb99e55fe|3d9f1800f327abb62228d7a9d28b711564a1176a22e421b45a8c1dc7057ff194|3d9f1800f327abb62228d7a9d28b711564a1176a22e421b45a8c1dc7057ff194', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-rewrite1-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Kaminal Juyu Parque Arqueológico, a Maya site in Guatemala City, had some 200 platforms and pyramidal mounds when first mapped scientifically; huge thrones and stelae attest to its might."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check1-001 (check1), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the site is a Maya site [S1]; the site is in Guatemala City [S1]; when first mapped scientifically it comprised some 200 platforms and pyramidal mounds [S2]; there are huge (enormous) thrones and stelae [S7]; the thrones and stelae attest to the site''s might [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-012 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Kaminal Juyu (Kaminaljuyu) is a site of the Maya civilization [SUPPORTED: https://en.wikipedia.org/wiki/Kaminaljuyu]; The site is located in Guatemala City, Guatemala [SUPPORTED: https://en.wikipedia.org/wiki/Kaminaljuyu]; The site comprised some 200 platforms and pyramidal mounds [SUPPORTED: https://en.wikipedia.org/wiki/Kaminaljuyu]; The count of 200 refers to the time when the site was first mapped scientifically [SUPPORTED: https://en.wikipedia.org/wiki/Kaminaljuyu]; The site has huge thrones [SUPPORTED: https://en.wikipedia.org/wiki/Kaminaljuyu]; The site has stelae [SUPPORTED: https://en.wikipedia.org/wiki/Kaminaljuyu]; The thrones and stelae attest to the site''s might [SUPPORTED: https://en.wikipedia.org/wiki/Kaminaljuyu]; A portion of the site is preserved as an archaeological park (Parque Arqueologico) [SUPPORTED: https://en.wikipedia.org/wiki/Kaminaljuyu]"}]'::jsonb),
    ('29bbdfce-7b18-4530-b668-8a2fb289694b'::uuid, 'card_description', 'From 7500 to 4000 BP, Qillqatani was inhabited by hunter-gatherers as a seasonal campsite.', 'Above the Rio Chila lie the elaborate rock art panels of Qillqatani, where 36 cultural strata hold hunters of camelids and some deer, then herders who built houses and stayed.', 'teaser-card-s012:29bbdfce-7b18-4530-b668-8a2fb289694b:card_description', 'teaser-card-s012 (teaser-card): teaser card, 175 characters, checked PASS, web-verified VERIFIED', 'b0a3f0f65f491eb1e7e676d0d9b95ca414b702124feef0053082b22597ec69f1|d71f5347642c9f1bf4e4fef6f74ab277b10fa664abf6b6e8d4665eb9a372100d|d71f5347642c9f1bf4e4fef6f74ab277b10fa664abf6b6e8d4665eb9a372100d', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-005", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Above the Rio Chila lie the elaborate rock art panels of Qillqatani, where 36 cultural strata hold hunters of camelids and some deer, then herders who built houses and stayed."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-005 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Qillqatani lies above the Rio Chila [S2]; Qillqatani has elaborate rock art panels [S3]; the site has 36 cultural strata [S5]; the site was occupied by hunters [S6]; those hunters hunted camelids and some deer [S7]; later the site was occupied by herders [S6, S8]; the herders built houses [S8]; the herders stayed, occupying the site long-term [S8]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-013 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Qillqatani is an archaeological site (central claim: what kind of place) [SUPPORTED: https://en.wikipedia.org/wiki/Qillqatani]; The site is in Peru [SUPPORTED: https://en.wikipedia.org/wiki/Qillqatani]; The site lies above the Rio Chila [SUPPORTED: https://en.wikipedia.org/wiki/Qillqatani]; The site has rock art panels [SUPPORTED: https://en.wikipedia.org/wiki/Qillqatani]; The rock art panels are elaborate [SUPPORTED: https://en.wikipedia.org/wiki/Qillqatani]; Archaeologists have identified 36 cultural strata at the site [SUPPORTED: https://en.wikipedia.org/wiki/Qillqatani]; The early occupants were hunters of camelids [SUPPORTED: https://en.wikipedia.org/wiki/Qillqatani]; The early occupants also hunted some deer [SUPPORTED: https://en.wikipedia.org/wiki/Qillqatani]; The hunters came first, then herders (sequence of occupation) [SUPPORTED: https://en.wikipedia.org/wiki/Qillqatani]; The later occupants were herders who built houses [SUPPORTED: https://en.wikipedia.org/wiki/Qillqatani]; The herders stayed (occupied the site long-term) [SUPPORTED: https://en.wikipedia.org/wiki/Qillqatani]"}]'::jsonb),
    ('29e8f8a9-119e-4cb7-8c24-c1ebd943cfe3'::uuid, 'card_description', 'Around 1900, the archaeologist Zacharie Le Rouzic again excavated the Saint-Michel tumulus and discovered a second dolmen and fifteen small stone chests.', 'East of Carnac rises the Saint-Michel Tumulus, the largest grave mound in continental Europe: earth and stones 125 metres long, hiding a second dolmen and fifteen small stone chests.', 'teaser-card-s012:29e8f8a9-119e-4cb7-8c24-c1ebd943cfe3:card_description', 'teaser-card-s012 (teaser-card): teaser card, 182 characters, checked PASS, web-verified VERIFIED', 'c54bedc61ec88e1a24406694aced9350ab80bc2489940431797e5a4db62aa176|bde620356d92d0fc3fdaaa2043007c5d44e4c10a3c52520091aac337ad5b399c|bde620356d92d0fc3fdaaa2043007c5d44e4c10a3c52520091aac337ad5b399c', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-005", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "East of Carnac rises the Saint-Michel Tumulus, the largest grave mound in continental Europe: earth and stones 125 metres long, hiding a second dolmen and fifteen small stone chests."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-005 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the Saint-Michel Tumulus lies east of Carnac [S1]; it is a grave mound [S1]; it is the largest grave mound in continental Europe [S2]; it is made of earth and stones [S4]; it is 125 metres long [S4]; it contains a second dolmen [S5]; it contains fifteen small stone chests [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-013 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "The Saint-Michel Tumulus is a grave mound (central claim: what kind of place) [SUPPORTED: https://en.wikipedia.org/wiki/Saint-Michel_tumulus]; It lies east of Carnac [SUPPORTED: https://en.wikipedia.org/wiki/Saint-Michel_tumulus]; It is the largest grave mound in continental Europe [SUPPORTED: https://en.wikipedia.org/wiki/Saint-Michel_tumulus]; The mound is made of earth and stones [SUPPORTED: https://en.wikipedia.org/wiki/Saint-Michel_tumulus]; The mound is 125 metres long [SUPPORTED: https://en.wikipedia.org/wiki/Saint-Michel_tumulus]; It hides a second dolmen (found by Le Rouzic around 1900) [SUPPORTED: https://en.wikipedia.org/wiki/Saint-Michel_tumulus]; Small stone chests lie inside the mound [SUPPORTED: https://fr.wikipedia.org/wiki/Tumulus_Saint-Michel]; The number of small stone chests is fifteen (English Wikipedia says fifteen, but French Wikipedia counts five annex chests plus a series of fourteen small chests, and another page says twenty-one chests around the central tomb; no page settles the number) [UNVERIFIABLE, no proving quote: None]"}]'::jsonb),
    ('2a4b62ce-c1d8-4def-ba57-ec8c77edb502'::uuid, 'card_description', 'Ten millstone grit stones form a ring 10.8 metres across on Stanton Moor. A lone outlier called the King Stone stands to the southwest, watching over the circle.', 'On the heathland of Stanton Moor stands the Nine Ladies Stone Circle, 10.8 m across, its stones cut from local millstone grit. In 1782 an antiquarian took it for a Druid temple.', 'teaser-card-s012:2a4b62ce-c1d8-4def-ba57-ec8c77edb502:card_description', 'teaser-card-s012 (teaser-card): teaser card, 177 characters, checked PASS, web-verified VERIFIED', 'eaefb5f0f88c0fccc67649582b424a4eed55ad98f3ebf5b471efbe7883a97a8a|8c65190de08d8a8bd8b35ad677fb0b482f3719f0203f01e09adfdc6a966ff89d|8c65190de08d8a8bd8b35ad677fb0b482f3719f0203f01e09adfdc6a966ff89d', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-005", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "On the heathland of Stanton Moor stands the Nine Ladies Stone Circle, 10.8 m across, its stones cut from local millstone grit. In 1782 an antiquarian took it for a Druid temple."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-005 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the Nine Ladies Stone Circle stands on Stanton Moor [S1, S3]; Stanton Moor is heathland [S3]; it is a stone circle [S1]; it is 10.8 m across [S5]; its stones are of millstone grit [S7]; the millstone grit is local [S7]; in 1782 an antiquarian considered it a Druid temple [S8]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-013 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "The Nine Ladies is a stone circle (central claim: what kind of place) [SUPPORTED: https://en.wikipedia.org/wiki/Nine_Ladies]; It stands on Stanton Moor [SUPPORTED: https://en.wikipedia.org/wiki/Nine_Ladies]; Stanton Moor is heathland [SUPPORTED: https://en.wikipedia.org/wiki/Nine_Ladies]; The circle is 10.8 m across [SUPPORTED: https://en.wikipedia.org/wiki/Nine_Ladies]; The stones are of millstone grit [SUPPORTED: https://en.wikipedia.org/wiki/Nine_Ladies]; The millstone grit is local [SUPPORTED: https://en.wikipedia.org/wiki/Nine_Ladies]; The date 1782 (Rooke''s article) [SUPPORTED: https://en.wikipedia.org/wiki/Nine_Ladies]; The one who took it for a Druid temple was an antiquarian (Hayman Rooke) [SUPPORTED: https://en.wikipedia.org/wiki/Nine_Ladies]; The antiquarian took it for a Druid temple [SUPPORTED: https://en.wikipedia.org/wiki/Nine_Ladies]"}]'::jsonb),
    ('2a535811-de40-4aa8-9768-ebbd9c43f22a'::uuid, 'card_description', 'Iron Age hill fort above the River Lemon in Devon, 75 metres up on a promontory above Bradley Manor. Its single limestone rampart and sunken approach were first described in print in 1950.', 'On a commanding promontory above the River Lemon, with views down the Teign Estuary, the Iron Age hill fort of Berry''s Wood rings the remains of huts with a limestone rampart.', 'teaser-card-s012:2a535811-de40-4aa8-9768-ebbd9c43f22a:card_description', 'teaser-card-s012 (teaser-card): teaser card, 175 characters, checked PASS, web-verified VERIFIED', 'bb3ece5704551de6915ad9e90d557c769a8714866a885bd00594e64d34959c3e|f56b7ae62a104e347b7d7bf28dd9507f6d3a2cc0a515a22182be0cfc090f771c|f56b7ae62a104e347b7d7bf28dd9507f6d3a2cc0a515a22182be0cfc090f771c', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-005", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "On a commanding promontory above the River Lemon, with views down the Teign Estuary, the Iron Age hill fort of Berry''s Wood rings the remains of huts with a limestone rampart."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-005 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Berry''s Wood sits on a commanding promontory [S2]; the promontory is above the River Lemon [S2]; it has views down the Teign Estuary [S2]; Berry''s Wood is an Iron Age hill fort [S1]; remains of huts lie inside it [S6]; its defences include a limestone rampart [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-013 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Berry''s Wood is a hill fort (central claim: what kind of place) [SUPPORTED: https://en.wikipedia.org/wiki/Berry%27s_Wood]; The hill fort is Iron Age [SUPPORTED: https://en.wikipedia.org/wiki/Berry%27s_Wood]; It stands on a commanding promontory [SUPPORTED: https://en.wikipedia.org/wiki/Berry%27s_Wood]; The promontory is above the River Lemon [SUPPORTED: https://en.wikipedia.org/wiki/Berry%27s_Wood]; It has views down the Teign Estuary [SUPPORTED: https://en.wikipedia.org/wiki/Berry%27s_Wood]; The remains of huts can be seen inside the fort [SUPPORTED: https://en.wikipedia.org/wiki/Berry%27s_Wood]; The rampart is limestone [SUPPORTED: https://en.wikipedia.org/wiki/Berry%27s_Wood]; The rampart encloses (rings) the huts [SUPPORTED: https://en.wikipedia.org/wiki/Berry%27s_Wood]"}]'::jsonb),
    ('2b2d0e62-5cbc-4427-be06-542064fb5076'::uuid, 'card_description', 'Poor Lot Barrow Cemetery is an archaeological site, a group of Bronze Age round barrows, near the A35 road about 2 miles west of Winterbourne Abbas, in Dorset.', 'Not on a ridge but on low-lying ground near the head of a valley lie the Bronze Age round barrows of Poor Lot Barrow Cemetery, from about 1500 BC. From a minor plateau, all can be seen.', 'teaser-card-s012:2b2d0e62-5cbc-4427-be06-542064fb5076:card_description', 'teaser-card-s012 (teaser-card): teaser card, 185 characters, checked PASS, web-verified VERIFIED', 'a9d9a18da1aa05d3fc98bf6d96bf30d5f9fe2bbc19adbbf187d0b95e1b41433e|ef7c90b83f76fb50ef23dcc0fb25d9a80fa2ce5ad17df8ebb55ecb7dc48f0911|ef7c90b83f76fb50ef23dcc0fb25d9a80fa2ce5ad17df8ebb55ecb7dc48f0911', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-005", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Not on a ridge but on low-lying ground near the head of a valley lie the Bronze Age round barrows of Poor Lot Barrow Cemetery, from about 1500 BC. From a minor plateau, all can be seen."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-005 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the barrows are not on a ridge [S2]; the barrows lie on low-lying ground [S2]; the site is near the head of a valley [S2]; Poor Lot Barrow Cemetery is a group of Bronze Age round barrows [S1]; the barrows date from about 1500 BC [S4]; all the barrows can be seen from a minor plateau [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-013 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Poor Lot Barrow Cemetery is a group of round barrows (central claim: what kind of place) [SUPPORTED: https://en.wikipedia.org/wiki/Poor_Lot_Barrow_Cemetery]; The round barrows are Bronze Age [SUPPORTED: https://en.wikipedia.org/wiki/Poor_Lot_Barrow_Cemetery]; The barrows are not on a ridge [SUPPORTED: https://en.wikipedia.org/wiki/Poor_Lot_Barrow_Cemetery]; The barrows are on low-lying ground [SUPPORTED: https://en.wikipedia.org/wiki/Poor_Lot_Barrow_Cemetery]; The site is near the head of a valley [SUPPORTED: https://en.wikipedia.org/wiki/Poor_Lot_Barrow_Cemetery]; The barrows date from about 1500 BC [SUPPORTED: https://en.wikipedia.org/wiki/Poor_Lot_Barrow_Cemetery]; There is a minor plateau at the site [SUPPORTED: https://en.wikipedia.org/wiki/Poor_Lot_Barrow_Cemetery]; From the minor plateau all the barrows can be seen [SUPPORTED: https://en.wikipedia.org/wiki/Poor_Lot_Barrow_Cemetery]"}]'::jsonb),
    ('2bf56725-c490-4536-9db2-1144983e477f'::uuid, 'card_description', '9th-millennium BC farming village, the oldest confirmed in the world. Klimonas was a circular subterranean building 10 metres across; cereals came from the Levant alongside domesticated hunting dogs.', 'At Ayios Tychonas in the Limassol District of Cyprus lies Klimonas, a village of the 9th millennium BC. Its people hunted wild boar; its cereals and cats came from the Levant.', 'teaser-card-s012:2bf56725-c490-4536-9db2-1144983e477f:card_description', 'teaser-card-s012 (teaser-card): teaser card, 175 characters, checked PASS, web-verified VERIFIED', '95f240295effc7784cff692a7c8d1183260490773f60247f5ce4e36ca400f2a3|6ed18fe2952a7cd58d38ec5356200d57a96c753f212bcf447cbc1cce995e6812|6ed18fe2952a7cd58d38ec5356200d57a96c753f212bcf447cbc1cce995e6812', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-rewrite-v-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "At Ayios Tychonas in the Limassol District of Cyprus lies Klimonas, a village of the 9th millennium BC. Its people hunted wild boar; its cereals and cats came from the Levant."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-v-001 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Klimonas lies at Ayios Tychonas [S2]; it lies in the Limassol District of Cyprus [S2]; Klimonas was a village [S2]; it dates to the 9th millennium BC [S1]; its people hunted wild boar [S4, S5]; its cereals came from the Levant [S4]; its cats came from the Levant [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify2-002 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Klimonas is a village (a farming village) [SUPPORTED: https://archeologie.culture.gouv.fr/en/klimonas-neolithization-cyprus]; Klimonas lies at Ayios Tychonas [SUPPORTED: https://en.wikipedia.org/wiki/Klimonas]; Klimonas lies in the Limassol District [SUPPORTED: https://en.wikipedia.org/wiki/Klimonas]; Klimonas is in Cyprus [SUPPORTED: https://en.wikipedia.org/wiki/Klimonas]; The village dates to the 9th millennium BC [SUPPORTED: https://en.wikipedia.org/wiki/Klimonas]; The people of Klimonas hunted wild boar [SUPPORTED: https://archeologie.culture.gouv.fr/en/klimonas-neolithization-cyprus]; Its cereals came from the Levant [SUPPORTED: https://en.wikipedia.org/wiki/Klimonas]; Its cats came from the Levant [SUPPORTED: https://en.wikipedia.org/wiki/Klimonas]"}]'::jsonb),
    ('2c05946f-80d4-4caf-8294-f1e2948d69b9'::uuid, 'card_description', 'Atella was a city of Oscan origin, one of the oldest in Campania and one of the first to have obtained the Roman civitas.', 'Atella, an Oscan city north of Naples, sided with Carthage after Cannae. Rome occupied it in 210 BC and executed its chief citizens, yet ruins of walls, houses and tombs remain.', 'teaser-card-s012:2c05946f-80d4-4caf-8294-f1e2948d69b9:card_description', 'teaser-card-s012 (teaser-card): teaser card, 177 characters, checked PASS, web-verified VERIFIED', '13e201f0389b6cb940087a00501f771ad752fda27777504059906ccf2c1b3624|cef47eea802fd279bf86c69b393268e40a9664f0684185c08a7fc493e2b80d74|cef47eea802fd279bf86c69b393268e40a9664f0684185c08a7fc493e2b80d74', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-005", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Atella, an Oscan city north of Naples, sided with Carthage after Cannae. Rome occupied it in 210 BC and executed its chief citizens, yet ruins of walls, houses and tombs remain."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-005 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Atella was an Oscan city [S1, S3]; it lies north of Naples [S1]; it sided with Carthage after the battle of Cannae [S5]; Rome occupied it in 210 BC [S6]; Rome executed its chief citizens [S6]; ruins of its walls remain [S2]; ruins of its houses remain [S2]; its tombs remain [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-014 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Atella was an ancient city (settlement) north of Naples, in Campania, Italy [SUPPORTED: https://en.wikipedia.org/wiki/Atella]; Atella was an Oscan city [SUPPORTED: https://en.wikipedia.org/wiki/Atella]; Atella sided with Carthage after the battle of Cannae [SUPPORTED: https://en.wikipedia.org/wiki/Atella]; Rome occupied Atella in 210 BC [SUPPORTED: https://en.wikipedia.org/wiki/Atella]; Rome executed Atella''s chief citizens [SUPPORTED: https://en.wikipedia.org/wiki/Atella]; Ruins of the city walls remain [SUPPORTED: https://en.wikipedia.org/wiki/Atella]; Ruins of houses remain [SUPPORTED: https://en.wikipedia.org/wiki/Atella]; Ruins of tombs remain [SUPPORTED: https://en.wikipedia.org/wiki/Atella]"}]'::jsonb),
    ('2cabb7a1-0596-457c-b37f-c041440b4fe2'::uuid, 'card_description', 'The Odeon of Herodes Atticus is a stone Greek theatre structure located on the southwest slope of the Acropolis of Athens.', NULL, 'teaser-card-s012:2cabb7a1-0596-457c-b37f-c041440b4fe2:card_description', 'teaser-card-s012 (card-clear-unproven-after-verify): card cleared (unproven-after-verify)', '||e848597824a17c704b110806cbbdaf089eb6ccee558d514ded1b1942199f867b', '[{"source": "lane WB run wb-ws-2026-09-27-01: unproven-after-verify", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "The web check could not prove: The Odeon of Herodes Atticus is a stone theatre (an odeon); The web check could not prove: It lies on the southwest slope of the Acropolis of Athens; The web check could not prove: The Odeon of Herodes Atticus is a building (a stone Greek theatre structure) in Athens, Greece"}]'::jsonb),
    ('2d35e0fe-b551-47db-b86d-30b2c3aad3aa'::uuid, 'card_description', 'A massive Saxon Shore fort founded after the conquest of 43 AD, with substantial walls still standing. Rutupiae was the main Roman gateway into the province and the origin of the name Britannia.', 'The massive walls of Richborough Castle still stand several metres high: a Roman Saxon Shore fort added around the year 277, believed to have been built by the rebel Carausius.', 'teaser-card-s012:2d35e0fe-b551-47db-b86d-30b2c3aad3aa:card_description', 'teaser-card-s012 (teaser-card): teaser card, 176 characters, checked PASS, web-verified VERIFIED', '0a6ba4f9a840ca938f50e64bc22ce0cf4173e4e6f5b03a3388174f211e29925c|4b61e10867b5b9fedf8129a6de232f6b64254573d4b7f41087aac51123929ccc|4b61e10867b5b9fedf8129a6de232f6b64254573d4b7f41087aac51123929ccc', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-005", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "The massive walls of Richborough Castle still stand several metres high: a Roman Saxon Shore fort added around the year 277, believed to have been built by the rebel Carausius."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-005 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Richborough Castle has massive walls [S3]; the walls still stand several metres high [S3]; it is a Roman Saxon Shore fort [S1]; the fort was added around the year 277 [S7]; it is believed to have been built by the rebel Carausius [S8]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-014 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Richborough Castle is a Roman Saxon Shore fort [SUPPORTED: https://en.wikipedia.org/wiki/Richborough_Castle]; Its massive walls still stand several metres high [SUPPORTED: https://en.wikipedia.org/wiki/Richborough_Castle]; The Saxon Shore fort was added (to the older site) around the year 277 [SUPPORTED: https://en.wikipedia.org/wiki/Richborough_Castle]; The fort is believed to have been built by the rebel Carausius (caveat: the same article dates construction 277-285 while Carausius usurped power only in 286; the source states the belief, hedged as the card does) [SUPPORTED: https://en.wikipedia.org/wiki/Richborough_Castle]; Carausius was a rebel (usurper) Roman commander [SUPPORTED: https://en.wikipedia.org/wiki/Carausius]"}]'::jsonb),
    ('2d786593-6e3f-40a9-8113-8012f6c2d35e'::uuid, 'card_description', 'The Monument of Aemilius Paullus was erected in the Sanctuary of Apollo at Delphi shortly after 167 BCE in order to commemorate the Roman victory over King Perseus of Macedon at the Battle of Pydna.', 'At Delphi, a pillar once meant for a portrait of King Perseus became the Monument of Aemilius Paullus, crowned by a bronze equestrian statue and a frieze of the Battle of Pydna.', 'teaser-card-s012:2d786593-6e3f-40a9-8113-8012f6c2d35e:card_description', 'teaser-card-s012 (teaser-card): teaser card, 177 characters, checked PASS, web-verified VERIFIED', '06eebd467881b6e9ec58f128015f9b88b7faacb765b0f96da1a76f74d42b321b|3a9462696398009a744d3e72f823b2036ff53360631f268b5fc085c8fa75039a|3a9462696398009a744d3e72f823b2036ff53360631f268b5fc085c8fa75039a', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-005", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "At Delphi, a pillar once meant for a portrait of King Perseus became the Monument of Aemilius Paullus, crowned by a bronze equestrian statue and a frieze of the Battle of Pydna."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-005 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the Monument of Aemilius Paullus is at Delphi [S1]; it incorporates a pillar originally intended for a portrait of King Perseus [S2]; it is crowned by a bronze equestrian statue [S3]; it has a frieze at the top depicting the Battle of Pydna [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-014 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "The Monument of Aemilius Paullus is a pillar monument at Delphi (in the Sanctuary of Apollo) [SUPPORTED: https://en.wikipedia.org/wiki/Monument_of_Aemilius_Paullus]; The pillar was once meant for a portrait of King Perseus [SUPPORTED: https://en.wikipedia.org/wiki/Monument_of_Aemilius_Paullus]; The pillar of Perseus became (was repurposed as) the Monument of Aemilius Paullus [SUPPORTED: https://en.wikipedia.org/wiki/Monument_of_Aemilius_Paullus]; The monument was crowned by a bronze equestrian statue [SUPPORTED: https://en.wikipedia.org/wiki/Monument_of_Aemilius_Paullus]; The monument carried a frieze of the Battle of Pydna [SUPPORTED: https://en.wikipedia.org/wiki/Monument_of_Aemilius_Paullus]"}]'::jsonb),
    ('2da62cd0-6900-4668-b490-220fdc6b1b49'::uuid, 'card_description', 'Leaze stone circle is a stone circle located in the parish of St. Breward on Bodmin Moor in Cornwall.', 'In a pasture on Bodmin Moor stands Leaze Stone Circle: sixteen squarish granite stones, six of them fallen, cut through the centre by a hedge. Once there may have been twenty two.', 'teaser-card-s012:2da62cd0-6900-4668-b490-220fdc6b1b49:card_description', 'teaser-card-s012 (teaser-card): teaser card, 179 characters, checked PASS, web-verified VERIFIED', '2155222e7be6d954d61cf7ae6aca6f0669056ef528af7d37b3e623978b250ae1|f2fb9cf463eb320d3389814c9975a7853602dc9cf41db6879bfc25bd69c59450|f2fb9cf463eb320d3389814c9975a7853602dc9cf41db6879bfc25bd69c59450', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-005", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "In a pasture on Bodmin Moor stands Leaze Stone Circle: sixteen squarish granite stones, six of them fallen, cut through the centre by a hedge. Once there may have been twenty two."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-005 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Leaze Stone Circle stands in a pasture [S2]; it is on Bodmin Moor [S1]; it is a stone circle [S1]; it is composed of sixteen stones [S2]; the stones are squarish granite [S6]; six of the stones have fallen [S2]; a hedge cuts through the centre of the circle [S3]; the circle may once have had twenty two stones (an estimate) [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-015 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Leaze Stone Circle is a stone circle [SUPPORTED: https://en.wikipedia.org/wiki/Leaze_stone_circle]; The site lies on Bodmin Moor [SUPPORTED: https://en.wikipedia.org/wiki/Leaze_stone_