    ('3a1d65e1-389c-4ceb-9eb1-50af9efeec1e'::uuid, 'card_description', 'Headland fort at 60 metres above Hope Cove in Devon, defended inland by a single linear earthwork. Little physical evidence of the structure remains above ground today.', 'Southwest of Hope Cove, the Devon headland of Bolt Tail once held an Iron Age promontory fort, some 60 metres above sea level and defended from inland by an earthwork. Little of it remains.', 'teaser-card-s012:3a1d65e1-389c-4ceb-9eb1-50af9efeec1e:card_description', 'teaser-card-s012 (teaser-card): teaser card, 189 characters, checked PASS, web-verified VERIFIED', '69ba81de2e7587505be421e6b38f1c39b990a8ac7bafe1f8747c573bc1f781cd|c825ec0815c9fc8ef882337fea546b1520fffef4faf567817af3866c7b4ab5a2|c825ec0815c9fc8ef882337fea546b1520fffef4faf567817af3866c7b4ab5a2', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-007", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Southwest of Hope Cove, the Devon headland of Bolt Tail once held an Iron Age promontory fort, some 60 metres above sea level and defended from inland by an earthwork. Little of it remains."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-007 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Bolt Tail lies southwest of Hope Cove [S1]; Bolt Tail is a headland in Devon [S1]; Bolt Tail was the site of an Iron Age promontory fort [S2]; the fort lay some 60 metres above sea level [S2]; the fort was defended from inland by an earthwork [S2]; little of the fort remains [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-019 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Bolt Tail (Devon) held a fort: the site is a promontory fort [SUPPORTED: https://www.devon.gov.uk/historicenvironment/explore-devons-heritage/bolt-tail/]; The fort is of the Iron Age [SUPPORTED: https://en.wikipedia.org/wiki/Bolt_Tail]; Bolt Tail is a headland in Devon [SUPPORTED: https://en.wikipedia.org/wiki/Bolt_Tail]; Bolt Tail lies southwest of Hope Cove [SUPPORTED: https://en.wikipedia.org/wiki/Bolt_Tail]; The fort lies some 60 metres above sea level [SUPPORTED: https://en.wikipedia.org/wiki/Bolt_Tail]; The fort was defended from inland [SUPPORTED: https://en.wikipedia.org/wiki/Bolt_Tail]; The defence from inland was an earthwork [SUPPORTED: https://www.devon.gov.uk/historicenvironment/explore-devons-heritage/bolt-tail/]; Little of the fort remains [SUPPORTED: https://en.wikipedia.org/wiki/Bolt_Tail]"}]'::jsonb),
    ('3aa70cf2-d56b-4401-8a60-2cd12131827c'::uuid, 'card_description', 'The cave is situated in a limestone ridge approximately 4 km from the coastline.', 'On the walls of Koongine Cave, in a limestone ridge of South Australia, are finger markings made by Indigenous Australians. People lived here approximately 10,000 years ago.', 'teaser-card-s012:3aa70cf2-d56b-4401-8a60-2cd12131827c:card_description', 'teaser-card-s012 (teaser-card): teaser card, 173 characters, checked PASS, web-verified VERIFIED', '6401d3562d7f93359e86bfa50f537a2cbea395146bac90d9dd1d358aab754900|3221de02c9307cf4684262a01681de2443cb5da9fefd1508d9349458b28560c9|3221de02c9307cf4684262a01681de2443cb5da9fefd1508d9349458b28560c9', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-007", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "On the walls of Koongine Cave, in a limestone ridge of South Australia, are finger markings made by Indigenous Australians. People lived here approximately 10,000 years ago."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-007 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "finger markings made by Indigenous Australians are on the walls of Koongine Cave [S4]; the cave lies in a limestone ridge [S2]; the cave is in South Australia [S1]; people occupied the cave approximately 10,000 years ago [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-019 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Koongine Cave is a cave in South Australia [SUPPORTED: https://en.wikipedia.org/wiki/Koongine_Cave]; The cave lies in a limestone ridge [SUPPORTED: https://en.wikipedia.org/wiki/Koongine_Cave]; Finger markings made by Indigenous Australians are on the cave walls [SUPPORTED: https://en.wikipedia.org/wiki/Koongine_Cave]; People lived in the cave approximately 10,000 years ago [SUPPORTED: https://en.wikipedia.org/wiki/Koongine_Cave]"}]'::jsonb),
    ('3b04e370-3686-477d-a5c1-f1a6f7123c5f'::uuid, 'card_description', 'To the southeast of the tor, on a northeast-facing slope are the remains of Hundatorra, a deserted medieval village.', 'Southeast of the weathered granite of Hound Tor on Dartmoor lie the ruins of Hundatorra, a deserted medieval village of longhouses, built on land farmed originally in the Bronze Age.', 'teaser-card-s012:3b04e370-3686-477d-a5c1-f1a6f7123c5f:card_description', 'teaser-card-s012 (teaser-card): teaser card, 182 characters, checked PASS, web-verified VERIFIED', '54d444567b38b159be19ebf87fb7a5abe454bcae05c2550e7608b45d91f5f6fb|0ae865b3100c046203acf95de47e4aafeb0853d17196202669ef7cfc314c100d|0ae865b3100c046203acf95de47e4aafeb0853d17196202669ef7cfc314c100d', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-007", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Southeast of the weathered granite of Hound Tor on Dartmoor lie the ruins of Hundatorra, a deserted medieval village of longhouses, built on land farmed originally in the Bronze Age."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-007 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Hound Tor is weathered granite [S1]; Hound Tor is on Dartmoor [S1]; the ruins of Hundatorra lie southeast of the tor [S3]; Hundatorra is a deserted medieval village [S3]; the village has longhouses [S6]; the village was built on land farmed originally in the Bronze Age [S4]; the village ruins are part of the Hound Tor site [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-019 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Hundatorra is a village whose ruins lie at Hound Tor [SUPPORTED: https://en.wikipedia.org/wiki/Hound_Tor]; The village is a deserted medieval village [SUPPORTED: https://en.wikipedia.org/wiki/Hound_Tor]; The village ruins lie southeast of the tor [SUPPORTED: https://en.wikipedia.org/wiki/Hound_Tor]; The village consisted of longhouses [SUPPORTED: https://www.english-heritage.org.uk/visit/places/hound-tor-deserted-medieval-village/history/]; The village was built on land farmed originally in the Bronze Age [SUPPORTED: https://en.wikipedia.org/wiki/Hound_Tor]; Hound Tor is a tor on Dartmoor [SUPPORTED: https://en.wikipedia.org/wiki/Hound_Tor]; Hound Tor is weathered granite [SUPPORTED: https://en.wikipedia.org/wiki/Hound_Tor]; The village lies on Dartmoor near the granite of Hound Tor [SUPPORTED: https://www.english-heritage.org.uk/visit/places/hound-tor-deserted-medieval-village/history/]"}]'::jsonb),
    ('3b4f0f7c-3828-49a3-bd1a-5392e2a34731'::uuid, 'card_description', 'A Roman town at the junction of roads connecting three modern countries. Its amphitheatre, temple, and baths served a garrison guarding the vital Alpine passes.', 'Once Octodurus, a Gaulish settlement of the Veragri, Martigny fell to Rome in 57 BC, when Servius Galba held it to guard the pass of Poeninus. The city is known for its amphitheater.', 'teaser-card-s012:3b4f0f7c-3828-49a3-bd1a-5392e2a34731:card_description', 'teaser-card-s012 (teaser-card): teaser card, 182 characters, checked PASS, web-verified VERIFIED', 'f78498d9cc0cc59211af2d8494a318e3b56091ec67d2f130720f01992c7a5db8|3be98f94cc4caf5d4a1cc9cad65120040289315b2432f5afac3c1e3b430dd253|3be98f94cc4caf5d4a1cc9cad65120040289315b2432f5afac3c1e3b430dd253', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-007", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Once Octodurus, a Gaulish settlement of the Veragri, Martigny fell to Rome in 57 BC, when Servius Galba held it to guard the pass of Poeninus. The city is known for its amphitheater."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-007 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Martigny was once called Octodurus [S1]; it was a Gaulish settlement [S1, S3]; it was a settlement of the Veragri [S1]; it was conquered by Rome in 57 BC [S2]; Servius Galba occupied it [S2]; the occupation was to protect the pass of Poeninus [S2]; the city is known for its amphitheater [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-019 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Martigny was once Octodurus [SUPPORTED: https://www.ostia-antica.org/switzerland/vs/martigny.htm]; Octodurus was a Gaulish settlement [SUPPORTED: https://en.wikipedia.org/wiki/Martigny]; The Gaulish settlement was of the Veragri [SUPPORTED: https://www.ostia-antica.org/switzerland/vs/martigny.htm]; Octodurus fell to Rome [SUPPORTED: https://en.wikipedia.org/wiki/Martigny]; The fall to Rome was in 57 BC [SUPPORTED: https://en.wikipedia.org/wiki/Martigny]; Servius Galba held Octodurus [SUPPORTED: https://en.wikipedia.org/wiki/Martigny]; Galba held it to guard the pass of Poeninus [SUPPORTED: https://en.wikipedia.org/wiki/Martigny]; Martigny is known for its amphitheater [SUPPORTED: https://en.wikipedia.org/wiki/Martigny]"}]'::jsonb),
    ('3b7c9b7b-5792-4162-84ed-5663b1760d60'::uuid, 'card_description', 'The cave was first excavated by Holland in 1958, when he found Bronze Age pottery, human and animal bones, and a stone-flake knife of Langdale stone.', 'At least eight people were buried in Heaning Wood Bone Cave in Cumbria. Some of its bones come from a small girl given the name Ossick Lass, dated to between 9290 and 8925 BCE.', 'teaser-card-s012:3b7c9b7b-5792-4162-84ed-5663b1760d60:card_description', 'teaser-card-s012 (teaser-card): teaser card, 176 characters, checked PASS, web-verified VERIFIED', '80907fc199ca754e7f4c482cd58c7444ed102712f323d09d3eca466b7229d43b|1c2900af8ef843d7e09a74faa285f2318b02e5f8c259239f2bf85410c3a3d538|1c2900af8ef843d7e09a74faa285f2318b02e5f8c259239f2bf85410c3a3d538', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-007", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "At least eight people were buried in Heaning Wood Bone Cave in Cumbria. Some of its bones come from a small girl given the name Ossick Lass, dated to between 9290 and 8925 BCE."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-007 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "at least eight people were buried in Heaning Wood Bone Cave [S4]; the cave is in Cumbria [S1]; some of its bones come from a small girl (a female aged two and a half to three and a half) [S5]; she was given the name Ossick Lass [S6]; she is dated to between 9290 and 8925 BCE [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-019 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Heaning Wood Bone Cave is a cave in Cumbria [SUPPORTED: https://archaeologymag.com/2026/02/earliest-known-burial-in-northern-britain/]; At least eight people were buried in the cave [SUPPORTED: https://www.bbc.com/news/articles/c3ew318v2kzo]; Some of the cave bones come from a small girl [SUPPORTED: https://www.bbc.com/news/articles/c3ew318v2kzo]; The girl was given the name Ossick Lass [SUPPORTED: https://archaeologymag.com/2026/02/earliest-known-burial-in-northern-britain/]; The girl is dated to between 9290 and 8925 BCE [SUPPORTED: https://archaeologymag.com/2026/02/earliest-known-burial-in-northern-britain/]"}]'::jsonb),
    ('3bfe34ae-3a60-48fe-9773-8cd0ec838b46'::uuid, 'card_description', 'A major Neolithic temple sharing design features with the famous Ggantija and Hagar Qim temples. Nearby cart ruts and a dolmen add to the ritual landscape.', 'Southeast of the Ta'' Ċenċ plateau lies Borġ l-Imramma, a major temple-period building sharing some traits of temples like Ħaġar Qim, with cart ruts and a dolmen nearby.', 'teaser-card-s012:3bfe34ae-3a60-48fe-9773-8cd0ec838b46:card_description', 'teaser-card-s012 (teaser-card): teaser card, 168 characters, checked PASS, web-verified VERIFIED', 'fb51ab56c4202404ee438c9f85d6f6c123439a86852040076486d3d5d3d834b9|5795f1fda26a8225a2c33888de5499d0db9fc727608643cd5912a7d98f70a618|5795f1fda26a8225a2c33888de5499d0db9fc727608643cd5912a7d98f70a618', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-007", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Southeast of the Ta'' Ċenċ plateau lies Borġ l-Imramma, a major temple-period building sharing some traits of temples like Ħaġar Qim, with cart ruts and a dolmen nearby."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-007 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Borġ l-Imramma lies southeast of the Ta'' Ċenċ plateau [S2]; it is a major building of the temple period [S1]; it shares some characteristics of temples such as Ħaġar Qim [S4]; cart ruts are nearby [S3]; a dolmen is nearby [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-020 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Borġ l-Imramma is a building of the temple period (a temple-period building) [SUPPORTED: https://en.wikipedia.org/wiki/Bor%C4%A1_l-Imramma]; It is a major building [SUPPORTED: https://en.wikipedia.org/wiki/Bor%C4%A1_l-Imramma]; It lies southeast of the Ta'' Ċenċ plateau [SUPPORTED: https://en.wikipedia.org/wiki/Bor%C4%A1_l-Imramma]; It shares some traits of temples like Ħaġar Qim [SUPPORTED: https://en.wikipedia.org/wiki/Bor%C4%A1_l-Imramma]; Cart ruts are nearby [SUPPORTED: https://en.wikipedia.org/wiki/Bor%C4%A1_l-Imramma]; A dolmen is nearby [SUPPORTED: https://en.wikipedia.org/wiki/Bor%C4%A1_l-Imramma]"}]'::jsonb),
    ('3c771af0-6d1d-4a43-94ec-89ad5b476255'::uuid, 'card_description', 'A Roman outpost fort north of Hadrian''s Wall named Fanum Cocidi -- "Shrine of Cocidius," a war god worshipped in northern Britain. It served as an intelligence post.', 'North of Hadrian''s Wall, Bewcastle Roman Fort was an outpost possibly meant for scouting, shaped as an irregular hexagon. Six of its nine altars were dedicated to the god Cocidius.', 'teaser-card-s012:3c771af0-6d1d-4a43-94ec-89ad5b476255:card_description', 'teaser-card-s012 (teaser-card): teaser card, 180 characters, checked PASS, web-verified VERIFIED', 'f64816b1035cdcfe5a6c62644601b5670e12a056d62bbf3dd91b8380e150d76d|e9789a8dbcdc9ddad56f405a1798b5e18c054516ae8fdb9c029fff7ae84885eb|e9789a8dbcdc9ddad56f405a1798b5e18c054516ae8fdb9c029fff7ae84885eb', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-007", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "North of Hadrian''s Wall, Bewcastle Roman Fort was an outpost possibly meant for scouting, shaped as an irregular hexagon. Six of its nine altars were dedicated to the god Cocidius."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-007 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Bewcastle Roman Fort lies north of Hadrian''s Wall [S1]; it was an outpost fort [S1]; it was possibly meant for scouting (hedge kept) [S1]; it was shaped as an irregular hexagon [S4]; nine altars were found at the fort [S3]; six of them are dedicated to the god Cocidius [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-020 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Bewcastle Roman Fort was a Roman fort (an outpost fort) [SUPPORTED: https://en.wikipedia.org/wiki/Bewcastle_Roman_Fort]; It lay north of Hadrian''s Wall [SUPPORTED: https://en.wikipedia.org/wiki/Bewcastle_Roman_Fort]; It was an outpost [SUPPORTED: https://en.wikipedia.org/wiki/Bewcastle_Roman_Fort]; The outpost was possibly meant for scouting [SUPPORTED: https://en.wikipedia.org/wiki/Bewcastle_Roman_Fort]; The fort was shaped as an irregular hexagon [SUPPORTED: https://en.wikipedia.org/wiki/Bewcastle_Roman_Fort]; Nine altars were found at the site [SUPPORTED: https://en.wikipedia.org/wiki/Bewcastle_Roman_Fort]; Six of the nine altars were dedicated to the god Cocidius [SUPPORTED: https://en.wikipedia.org/wiki/Bewcastle_Roman_Fort]"}]'::jsonb),
    ('3ca796ab-fbcc-4d93-9991-e17bcb558587'::uuid, 'card_description', 'At 114 meters, Dodman Point is the highest headland on the south Cornwall coast. A granite cross erected in 1896 for navigators and Christian service sits atop the ancient promontory earthworks.', 'Once known as the Deadman, Dodman Point near Mevagissey is the highest headland on the south Cornwall coast, measuring 374 feet, and it hosts the remains of an Iron Age promontory fort.', 'teaser-card-s012:3ca796ab-fbcc-4d93-9991-e17bcb558587:card_description', 'teaser-card-s012 (teaser-card): teaser card, 185 characters, checked PASS, web-verified VERIFIED', '270add08b086a4ed6d50a5fd50aedd90804be44ab9bb532810524f8c1a8aa5d1|46e7eb227c6ca737324317476323ca953cde6e17f67246ec01ad5eff60817e6c|46e7eb227c6ca737324317476323ca953cde6e17f67246ec01ad5eff60817e6c', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-rewrite-v-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Once known as the Deadman, Dodman Point near Mevagissey is the highest headland on the south Cornwall coast, measuring 374 feet, and it hosts the remains of an Iron Age promontory fort."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-v-001 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Dodman Point was once known as the Deadman [S2]; Dodman Point is near Mevagissey [S1]; it is the highest headland on the south Cornwall coast [S1]; it measures 374 feet [S1]; it hosts the remains of a promontory fort [S3]; the fort is of the Iron Age [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify2-002 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Dodman Point is a headland near Mevagissey (Cornwall) [SUPPORTED: https://en.wikipedia.org/wiki/Dodman_Point]; Dodman Point is the highest headland on the south Cornwall coast [SUPPORTED: https://en.wikipedia.org/wiki/Dodman_Point]; It measures 374 feet [SUPPORTED: https://en.wikipedia.org/wiki/Dodman_Point]; It was once known as the Deadman [SUPPORTED: https://en.wikipedia.org/wiki/Dodman_Point]; It hosts remains of a fort [SUPPORTED: https://en.wikipedia.org/wiki/Dodman_Point]; The fort is of the Iron Age and is a promontory fort [SUPPORTED: https://en.wikipedia.org/wiki/Dodman_Point]"}]'::jsonb),
    ('3d8cb484-8b57-41fa-ab0d-203449c1c821'::uuid, 'card_description', 'Various cave entrances are exposed which have been occupied by humans for over 10,000 years, with a hillfort being built beside the combe in the Iron Age.', 'No river now runs through Burrington Combe, a limestone gorge in the Mendip Hills. Humans have occupied its cave entrances for over 10,000 years, and an Iron Age hill fort stood above.', 'teaser-card-s012:3d8cb484-8b57-41fa-ab0d-203449c1c821:card_description', 'teaser-card-s012 (teaser-card): teaser card, 184 characters, checked PASS, web-verified VERIFIED', 'f85879e61c83f133df9a4c13a5c60ecce1d6e8b7518b57c42c679f5efdc2b935|364c22548d59443afef1426ca0b451d822644660ab698e23aa4d3ea786475e04|364c22548d59443afef1426ca0b451d822644660ab698e23aa4d3ea786475e04', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-007", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "No river now runs through Burrington Combe, a limestone gorge in the Mendip Hills. Humans have occupied its cave entrances for over 10,000 years, and an Iron Age hill fort stood above."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-007 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "no river now runs through Burrington Combe [S2]; it is a limestone gorge [S1, S2]; it is in the Mendip Hills [S1]; humans have occupied its cave entrances for over 10,000 years [S3]; an Iron Age hill fort stood above the combe [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-020 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Burrington Combe is a limestone gorge [SUPPORTED: https://en.wikipedia.org/wiki/Burrington_Combe]; The gorge lies in the Mendip Hills [SUPPORTED: https://en.wikipedia.org/wiki/Burrington_Combe]; No river now runs through the combe [SUPPORTED: https://en.wikipedia.org/wiki/Burrington_Combe]; Humans have occupied its cave entrances for over 10,000 years [SUPPORTED: https://en.wikipedia.org/wiki/Burrington_Combe]; An Iron Age hill fort stood above the combe [SUPPORTED: https://en.wikipedia.org/wiki/Burrington_Combe]"}]'::jsonb),
    ('3db7a812-6b3a-4574-b804-840a2390cdad'::uuid, 'card_description', 'Baiae was built on the Cumaean Peninsula in the Phlegraean Fields, an active volcanic area, on the side of an ancient crater sloping down to the shore.', 'On the Gulf of Naples, wealthy Romans built villas at Baiae from 100 BC, on the side of an ancient crater. Later, volcanic activity sank the lower part of the town into the sea.', 'teaser-card-s012:3db7a812-6b3a-4574-b804-840a2390cdad:card_description', 'teaser-card-s012 (teaser-card): teaser card, 177 characters, checked PASS, web-verified VERIFIED', 'b61581c1c62c9b88492305a944b398055da6144c8c80a6298204f5060db91040|bfef55763204334c9cacd74a633efafd5f2cfe089e28531e2950810fc6e467e0|bfef55763204334c9cacd74a633efafd5f2cfe089e28531e2950810fc6e467e0', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-007", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "On the Gulf of Naples, wealthy Romans built villas at Baiae from 100 BC, on the side of an ancient crater. Later, volcanic activity sank the lower part of the town into the sea."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-007 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Baiae is on the Gulf of Naples [S1]; wealthy Romans built villas at Baiae [S2]; villa building began from 100 BC [S2]; Baiae was built on the side of an ancient crater [S4]; later, volcanic activity submerged the lower part of the town in the sea [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-020 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Baiae is an ancient Roman town (resort) [SUPPORTED: https://en.wikipedia.org/wiki/Baiae]; It lies on the Gulf of Naples [SUPPORTED: https://en.wikipedia.org/wiki/Baiae]; Wealthy Romans built villas at Baiae [SUPPORTED: https://en.wikipedia.org/wiki/Baiae]; The villas were built from 100 BC [SUPPORTED: https://en.wikipedia.org/wiki/Baiae]; Baiae was built on the side of an ancient crater [SUPPORTED: https://en.wikipedia.org/wiki/Baiae]; Later, volcanic activity sank the lower part of the town into the sea [SUPPORTED: https://en.wikipedia.org/wiki/Baiae]"}]'::jsonb);

DO $$
DECLARE
    bad      INTEGER;
    moved    INTEGER := 0;
    expected INTEGER := 100;
    r        RECORD;
BEGIN
    -- expected is the plan's own row count, rendered here, and not a second count of the
    -- temp table the loop below iterates: counting the same table twice would make the
    -- comparison after the loop a tautology. The instance that makes a short loop
    -- unreachable is apply_remediation_change, which raises unless exactly one row
    -- matched; this guard is what reports a loop that changed fewer rows than the plan.

    -- scope guard 1: every planned row is a card_stats row of a curated site that still exists
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p LEFT JOIN card_stats t ON t.site_id = p.site_id
      LEFT JOIN unified_sites u ON u.id = p.site_id
     WHERE t.site_id IS NULL OR u.id IS NULL OR u.source_id <> 'ancient_nerds';
    IF bad > 0 THEN
        -- the source name is a RAISE argument, never part of the quoted message: a name
        -- spliced into the message text only parses while the name happens to contain no
        -- quote, which is a property of today's value and not of this code. G0's guard is
        -- the shape this one copies.
        RAISE EXCEPTION 'teaser card: % planned row(s) are not % sites', bad, 'ancient_nerds';
    END IF;

    -- scope guard 2: the plan is a set of real changes, each one writable in its column
    -- (compared in the column's own type; CASE, because only CASE fixes the order in
    -- which the casts are evaluated)
    SELECT count(*) INTO bad FROM _teaser_card_plan p
     WHERE p.new_value = '' OR CASE p.column_name
                WHEN 'card_description' THEN p.new_value::character varying IS NOT DISTINCT FROM p.old_value::character varying OR length(p.new_value) > 200
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) are not writable changes', bad;
    END IF;

    -- scope guard 3: every planned row still holds the old value the plan names
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p JOIN card_stats t ON t.site_id = p.site_id
     WHERE CASE p.column_name
                WHEN 'card_description' THEN t.card_description IS DISTINCT FROM p.old_value::character varying
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) no longer hold the planned old value', bad;
    END IF;

    -- scope guard 5: every planned row still holds the input its value was derived from
    SELECT count(*) INTO bad
      FROM (SELECT DISTINCT site_id, premise FROM _teaser_card_plan) p JOIN unified_sites u ON u.id = p.site_id
     WHERE (coalesce(u.raw_data -> '_card_provenance' ->> 'text_sha256', '') || '|' || coalesce(u.raw_data -> '_card_provenance' ->> 'desc_sha256', '') || '|' || encode(sha256(convert_to(coalesce(u.description, ''), 'UTF8')), 'hex')) IS DISTINCT FROM p.premise;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) no longer hold the premise the plan derived its value from', bad;
    END IF;

    -- the only writer: the conditional UPDATE and its journal row commit together, and
    -- the function raises unless exactly one row matched
    FOR r IN SELECT * FROM _teaser_card_plan ORDER BY site_id, column_name LOOP
        moved := moved + apply_remediation_change(
            'card_stats', r.column_name, 'site_id', r.site_id::text,
            r.old_value, r.new_value,
            'WB/teaser-card', 'wb-teaser-card-s012', r.change_key, 'opus-checked', r.evidence, r.site_id);
    END LOOP;

    IF moved <> expected THEN
        RAISE EXCEPTION 'teaser card: % row(s) changed, % planned', moved, expected;
    END IF;

    -- invariant 1: every planned row now holds the new value
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p JOIN card_stats t ON t.site_id = p.site_id
     WHERE CASE p.column_name
                WHEN 'card_description' THEN t.card_description IS DISTINCT FROM p.new_value::character varying
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) do not hold the new value', bad;
    END IF;

    -- invariant 2: the journal and the data agree, row for row, in both directions
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p LEFT JOIN remediation_change_log l
        ON l.row_pk = p.site_id::text AND l.table_name = 'card_stats'
       AND l.column_name = p.column_name
       AND l.run_stamp = 'wb-teaser-card-s012'
     WHERE l.id IS NULL
        OR l.new_value IS DISTINCT FROM p.new_value
        OR l.old_value IS DISTINCT FROM p.old_value;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) have no matching journal row', bad;
    END IF;

    SELECT count(*) INTO bad FROM remediation_change_log l
     WHERE l.run_stamp = 'wb-teaser-card-s012'
       AND (l.table_name <> 'card_stats' OR l.column_name NOT IN ('card_description'));
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: this run stamp journalled % row(s) outside card_stats.(card_description)', bad;
    END IF;

    RAISE NOTICE 'teaser card: % of % planned cell(s) changed and journalled over 100 curated site(s)',
        moved, expected;
END $$;

COMMIT;

-- Post-commit read: the numbers the report quotes, from the database, not from the plan.
SELECT 'journal rows for this run stamp' AS metric, count(*)::text AS value
  FROM remediation_change_log WHERE run_stamp = 'wb-teaser-card-s012'
UNION ALL
SELECT 'journal rows for this test id', count(*)::text
  FROM remediation_change_log WHERE test_id = 'WB/teaser-card'
UNION ALL
SELECT 'planned rows now holding the new value', count(*)::text
  FROM remediation_change_log l
 WHERE l.run_stamp = 'wb-teaser-card-s012' AND l.table_name = 'card_stats'
   AND l.column_name IN ('card_description')
   AND EXISTS (SELECT 1 FROM card_stats t
                WHERE t.site_id::text = l.row_pk AND CASE l.column_name
                WHEN 'card_description' THEN t.card_description IS NOT DISTINCT FROM l.new_value::character varying
                ELSE false END)
UNION ALL
SELECT 'curated sites whose teaser provenance does not hash their live card', count(*)::text
  FROM unified_sites
 WHERE source_id = 'ancient_nerds' AND raw_data ? '_card_provenance' AND NOT EXISTS (SELECT 1 FROM card_stats cs WHERE cs.site_id = unified_sites.id AND encode(sha256(convert_to(cs.card_description, 'UTF8')), 'hex') = unified_sites.raw_data -> '_card_provenance' ->> 'text_sha256')
UNION ALL
SELECT 'curated sites', count(*)::text
  FROM unified_sites WHERE source_id = 'ancient_nerds';
